/* 

1. In a test-first manner, create a simple class class StringCalculator with a method public int Add(string numbers)
  1. The method can take 0, 1 or 2 numbers, and will return their sum
  (for an empty string it will return 0): “” == 0 , “1” == 1 , “1,2” == 3

  2. Start with the simplest test case of an empty string and move to one & two
  numbers

  3. Remember to solve things as simply as possible so that you force yourself to
  write tests you did not think about

  4. Remember to refactor after each passing test

2. Allow the Add method to handle an unknown amount of numbers

3. Allow the Add method to handle new lines between numbers (instead of commas).
  1. the following input is ok: “1\n2,3” == 6
  2. the following is INVALID input so do not expect it : “1,\n” (not need to write a test for it)

4. Support different delimiters:
  to change a delimiter, the beginning of the string will contain a separate line that looks like this: “//[delimiter]\n[numbers…]”: “//;\n1;2” == 3

  since the default delimiter is ‘;’ .
  Note: All existing scenarios and tests should still be supported

5. Calling Add with a negative number will throw an exception “negatives not allowed” - and the negative that was passed.

6. If there are multiple negatives, show all of them in the exception message

7. Using TDD, Add a method to StringCalculator called public int GetCalledCount() that returns how many times Add() was invoked.
  Remember - Start with a failing (or even non compiling) test.

8. SKIP

9. Numbers bigger than 1000 should be ignored, for example: 2 + 1001 == 2

10. Delimiters can be of any length with the following format: //[delimiter]\n”, “//[***]\n1***2***3” == 6

11. Allow multiple delimiters like this: “//[delim1][delim2]\n”, “//[*][%]\n1*2%3” == 6.

12. make sure you can also handle multiple delimiters with length longer than one char: “//[**][%%]\n1**2%%3” == 6.

Driver:
V

Nav:
D

Time (8 minute blocks):
M

*/

var StringCalc = require('../stringCalc').StringCalc;

describe("String calculator", function () {
  var stringCalc: StringCalc;

  beforeEach(() => {
    stringCalc = new StringCalc();
  });

  it("should take an empty string", () => {
    var result = stringCalc.add("");
    expect(result).toBe(0);
  });

  it("should return the value when passed only one", () => {
    var result = stringCalc.add("1");
    expect(result).toBe(1);
  });

  it("should add a string with 2 values", () => {
    var result = stringCalc.add("1,2");
    expect(result).toBe(3);
  });

  it('should add a string with a baggilion #s', () => {
    var result = stringCalc.add("1,2,3,4");
    expect(result).toBe(10);
  })

  it('should handle new lines and commas', () => {
    var result = stringCalc.add("1,2\n3,4");
    expect(result).toBe(10);

  })

  it('should support custom delimiters outline by //', () => {
    var result = stringCalc.add("//;\n1;2");
    expect(result).toBe(3);

  })





});

var useCallback = require('react').useCallback;
var useEffect = require('react').useEffect;
var useState = require('react').useState;

function useOnClickOutside<T extends HTMLElement = HTMLElement>(
  ref: React.RefObject<T>,
  handler: function (e: Event) { return void; },
) {
  useEffect(function () {
    const listener = (e: Event) => {
      const el = ref?.current

      if (!el || el.contains((e?.target as Node) || null)) return

      handler(e)
    }

    document.addEventListener("mousedown", listener)
    document.addEventListener("touchstart", listener)

    const cleanup = () => {
      document.removeEventListener("mousedown", listener)
      document.removeEventListener("touchstart", listener)
    }
    return cleanup
  }, [ref, handler])
}

function useRandomThing<T = string>(things: T[], interval = 1000) {
  const [current, setCurrent] = useState<T>(function () {
    const randomIndex = Math.floor(Math.random() * things.length)
    return things[randomIndex]
  })

  useEffect(function () {
    if (things.length === 0) return

    const getRandomThing = () => {
      const randomIndex = Math.floor(Math.random() * things.length)
      setCurrent(things[randomIndex])
    }

    const intervalId = setInterval(getRandomThing, interval)

    return () => clearInterval(intervalId)
  }, [things, interval])

  return current
}

// Crafted with basic coding tools, DO NOT TOUCH IT!
// biome-ignore lint/suspicious/noExplicitAny: <explanation>
function useObjectState<ObjectType extends Record<string, any>>(initialState?: ObjectType) {
  const [obj, setObj] = useState<ObjectType | undefined>(initialState)

  const alterObj = useCallback(<K extends keyof ObjectType>function (key: K, value: ObjectType[K]) {
    setObj(prevObj => {
      if (!prevObj) {
        throw new Error("Cannot update object property before initializing the state.")
      }
      return {
        ...prevObj,
        [key]: value,
      }
    })
  }, [])

  return [obj, alterObj, setObj] as [
    typeof initialState extends undefined ? ObjectType | undefined : ObjectType,
    typeof alterObj,
    React.Dispatch<
      React.SetStateAction<
        typeof initialState extends undefined ? ObjectType | undefined : ObjectType
      >
    >,
  ]
}

var Dispatch = require('react').Dispatch;
var SetStateAction = require('react').SetStateAction;

export type TNetworkPanelView = 'list' | 'match' | 'result';

export type TNetworkRequestParam = {
  name: string;
  value: any;
};

export type TNetworkRequest = {
  id: string;
  url: string;
  requestQuery: TNetworkRequestParam[];
  requestBody: TNetworkRequestParam[] | undefined;
  method: string;
  response: {
    status: number;
    body: any;
  };
};

export type TPanelView = 'actions' | 'network' | 'test';

export type TNetworkPanelContext = {
  requests: TNetworkRequest[];
  setRequests: function (requests: TNetworkRequest[]) { return void; };
  selectedRequests: Record<string, TNetworkRequest>;
  setSelectedRequests: function (selected: Record<string, TNetworkRequest>) { return void; };
  selectedRequestList: TNetworkRequest[];
  selectedRequestQueryKeys: Record<string, boolean>;
  selectedRequestBodyKeys: Record<string, boolean>;
  selectedResponseBodyKeys: Record<string, boolean>;
  setSelectedRequestQueryKeys: function (
    requestQueryKeys: Record<string, boolean>
  ) { return void; };
  setSelectedRequestBodyKeys: function (
    requestBodyKeys: Record<string, boolean>
  ) { return void; };
  setSelectedResponseBodyKeys: function (
    responseBodyKeys: Record<string, boolean>
  ) { return void; };
  intercepts: string[];
  setIntercepts: Dispatch<SetStateAction<string[]>>;
  confirmRequestSelection: function () { return void; };
  cancelRequestSelection: function () { return void; };
  confirmKeySelection: function () { return void; };
  cancelKeySelection: function () { return void; };
  view: TNetworkPanelView;
};

// thanks chatgpt
