var Scenario = require('../Scenario.js').Scenario;
var Channel = require('discord.js').Channel;
var Client = require('discord.js').Client;
var EmbedBuilder = require('discord.js').EmbedBuilder;
var User = require('discord.js').User;
var Lt = require('long-timeout');
var off = require('process').off;

export interface ShowOrMovie extends PollItem {}

const hoursToMs = 3600000;

function msToDurationString(durationMS: number): string {

	let durationSecs = durationMS / 1000;

	let days = Math.floor(durationSecs / (24 * 60 * 60));
	durationSecs = durationSecs % (24 * 60 * 60);

	let hours = Math.floor(durationSecs / (60 * 60));
	durationSecs = durationSecs % (60 * 60);

	let minutes = Math.floor(durationSecs / 60);
	let seconds = Math.floor(durationSecs % 60);

	return "" + (days > 0 	? days + "d " 		: "") + ""
		+ "" + (hours > 0 		? hours + "h " 		: "") + ""
		+ "" + (minutes > 0 	? minutes + "m " 	: "") + ""
		+ "" + (seconds > 0 	? seconds + "s " 	: "") + "";
}

export interface PollItem {
	uid: string;
	name: string,
	img_url: string,
	url: string
}

interface InternalItem<ItemType> {
	nominator: string,
	item: ItemType
}

interface SaveState<ItemType> {
	creatorID: string,
	nominationLimit: number,
	items: { [key: string]: InternalItem<ItemType> }
	voteTime: string,
	endTime: string,
	isVoting: boolean,
	votes: [string, string[]][]
}

module.exports = class PollScenario<ItemType extends Required<PollItem>> extends Scenario {;

	private _isVoting = false;
	private _creatorID: string = "";

	private _nominationLimit = 1;
	private _nominees: Map<string, InternalItem<ItemType>> = new Map;

	private _voteTime = new Date(0);
	private _voteTimeout: Lt.Timeout | null = null;

	private _endTime = new Date(0);
	private _endTimeout: Lt.Timeout | null = null;

	private _votes: Map<string, Array<string>> = new Map;

	// #region Scenario

	init(): void {

		this.loadState();
		this.updateVoteTimeout();
		this.updateEndTimeout();

	}

	shutdown() {

		if(this._voteTimeout)
			Lt.clearTimeout(this._voteTimeout);

		if(this._endTimeout)
			Lt.clearTimeout(this._endTimeout);

		this.controls.Clean();
	}

	get isPersistant() {
		return true;
	}

	// #endregion

	configurePoll(creatorID: string, hoursBeforeVote: number, hoursVoting: number, nominationLimit: number) {

		this._creatorID = creatorID;
		this._voteTime = new Date(Date.now() + (hoursBeforeVote * hoursToMs));
		this._endTime = new Date(this._voteTime.getTime() + (hoursVoting * hoursToMs));

		if(nominationLimit)
			this._nominationLimit = nominationLimit;

		this.saveState();
		this.updateVoteTimeout();
		this.updateEndTimeout();
	}

	isCreator(toCheck: User): boolean {
		return toCheck.id == this._creatorID;
	}

	isVoting(): boolean {
		return this._isVoting;
	}

	getVoteTime() : Date {
		return this._voteTime;
	}

	getEndTime() : Date {
		return this._endTime;
	}

	timeStatusString(): string {

		let out = "";
		let voteTime = this.getVoteTime();
		let voteTimeOffsetMS = voteTime.getTime() - Date.now();
		if(voteTimeOffsetMS > 0)
			out += "\nTime Until Vote: " + (msToDurationString(voteTimeOffsetMS)) + "";

		let endTime = this.getEndTime();
		let endTimeOffsetMs = endTime.getTime() - Math.max(voteTime.getTime(), Date.now());
		if(endTimeOffsetMs > 0)
			out += "\nVoting Time Left: " + (msToDurationString(endTimeOffsetMs)) + "";

		return out;
	}

	private async getMentionString() : Promise<string> {

		let mentionSet = new Set<string>();

		this._nominees.forEach(function (value) {
			mentionSet.add(value.nominator);
		});

		Array.from(this._votes.keys()).forEach(function (value) {
			mentionSet.add(value);
		});

		let out = "";
		let entryItr = mentionSet.entries();

		for(let [currUid] of entryItr) {

			let currUser = await this.client.users.fetch(currUid);
			out += "" + (currUser) + " ";

		}

		return out;

	}

	private onVoteTimeout = async function () {

		if(this._isVoting)
			return;

		this._isVoting = true;
		this.saveState();

		let mentionString = await this.getMentionString();

		let pollChannel = this.channel;
		if(pollChannel.isTextBased())
			pollChannel.send("" + (mentionString) + "\n\n The nomination period has ended, you may now vote. Use \`/poll vote\`.");

	}

	private onEndTimeout = async function () {

		let bordaCount = this.doBordaCount();

		let channel = this.channel;
		if(bordaCount.size <= 0 && channel.isTextBased()) {
			this.controls.End();
			return channel.send("Could not tally a winner; there were no votes.");
		}

		let sorted = sortMapToArray(bordaCount);
		let sortedItems = sorted.map((UID) => {
			return this._nominees.get(UID)!;
		});

		let maxPoints = (this._nominees.size - 1) * this._votes.size;
		let winner = sortedItems.splice(0, 1).at(0)!;
		sortedItems = sortedItems.splice(0, 25);
		let fields = sortedItems.map((currItem, index) => {

			let currCount = bordaCount.get(currItem.item.uid)!;
			return {
				name: "" + (index + 2) + ". " + (currItem.item.name) + "",
				value: "" + (currCount) + " Points (" + (currCount / maxPoints * 100) + "%)"
			}

		});

		if(channel.isTextBased()) {

			let mentions = await this.getMentionString();
			let winnerCount = bordaCount.get(winner.item.uid)!;
			channel.send({
				content: "" + (mentions) + "\n\n The poll has finished.",
				embeds: [{
					title: "**The winner is " + (winner.item.name) + "!**",
					description: "" + (winnerCount) + " Points (" + (winnerCount / maxPoints * 100) + "%)",
					image: { url: winner.item.img_url },
					color: 0xd4af37
				}, 

				new EmbedBuilder()
					.setFields(fields)
					.setColor(0xaaa9ad)

				]
			});

		}

		this.controls.End();
	}

	private saveState() {

		this.controls.Save({
			nominationLimit: this._nominationLimit,
			items: Object.fromEntries(this._nominees),
			voteTime: this._voteTime.toISOString(),
			endTime: this._endTime.toISOString(),
			isVoting: this._isVoting,
			creatorID: this._creatorID,
			votes: Array.from(this._votes.entries())
		} as SaveState<ItemType>);

	}

	private loadState() {

		let state = this.controls.Load() as SaveState<ItemType>;
		if(!state) return;
		if(Object.keys(state).length <= 0) return;

		this._nominationLimit = state.nominationLimit;
		this._nominees = new Map(Object.entries(state.items));
		this._voteTime = new Date(state.voteTime);
		this._endTime = new Date(state.endTime);
		this._isVoting = state.isVoting;
		this._creatorID = state.creatorID;
		this._votes = new Map(state.votes);

	}

	private canAddItem(nominatorID: string, toAdd: ItemType) : string | undefined {

		if(this._nominees.has(toAdd.uid))
			return "Item already exists.";

		let found = Array.from(this._nominees.entries()).filter(function ([UID, nominee]) {
			return nominee.nominator == nominatorID;
		});

		if(found.length >= this._nominationLimit)
			return "Item limit reached. (" + (this._nominationLimit) + ")";

		return undefined;
	}

	addItem(nominatorID: string, toAdd: ItemType) : string | undefined{

		if(this._isVoting)
			return "Items cannot be added while the poll is voting.";

		let res = this.canAddItem(nominatorID, toAdd);
		if(res) return res;

		this._nominees.set(toAdd.uid, {nominator: nominatorID, item: toAdd});
		this.saveState();

		return undefined;

	}

	private canRemoveItem(nominatorID: string, uid: string, admin: boolean): string | undefined {

		if(!this._nominees.has(uid))
			return "Item doesn't exist.";

		let currItem = this._nominees.get(uid);
		if(!currItem)
			return "Failed to get item.";

		if(currItem.nominator != nominatorID && !admin)
			return "You do not have permission to remove that item.";

		return undefined;
	}

	removeItem(uid: string, nominatorID: string, admin: boolean) {

		if(this._isVoting)
			return "Items cannot be removed while the poll is voting.";

		let res = this.canRemoveItem(nominatorID, uid, admin);
		if(res) return res;

		this._nominees.delete(uid);
		this.saveState();

		return undefined;
	}

	getItem(uid: string) : ItemType | undefined {

		if(!this._nominees.has(uid))
			return undefined;

		return this._nominees.get(uid)?.item;

	}

	getNomineeList() : Array<ItemType> {

		return Array.from(this._nominees.values()).map(function (internalItem) {
			return internalItem.item;
		});

	}

	setVoteTime(time: Date) {

		let offset = this._endTime.getTime() - this._voteTime.getTime();

		this._voteTime = time;
		this.saveState();
		this.updateVoteTimeout();

		this.setEndTime(new Date(this._voteTime.getTime() + offset));
	}

	setEndTime(time: Date) {

		this._endTime = time;
		this.saveState();
		this.updateEndTimeout();

	}

	private updateVoteTimeout() {

		let timeToVote = this._voteTime.getTime() - Date.now();

		if(this._voteTimeout)
			Lt.clearTimeout(this._voteTimeout);

		this._voteTimeout = Lt.setTimeout(this.onVoteTimeout, timeToVote);

	}

	private updateEndTimeout() {

		let timeToEnd = this._endTime.getTime() - Date.now();

		if(this._endTimeout)
			Lt.clearTimeout(this._endTimeout);

		this._endTimeout = Lt.setTimeout(this.onEndTimeout, timeToEnd);

	}

	setVote(userID: string, ranks: Array<string>) {

		this._votes.set(userID, ranks);
		this.saveState();

	}

	doBordaCount() : Map<string, number> {

		let outMap = new Map<string, number>();

		this._votes.forEach(function (rankList) {

			rankList.forEach((itemUID, index) => {

				if(!outMap.has(itemUID))
					outMap.set(itemUID, 0);

				let pointValue = this._nominees.size - (index + 1);
				outMap.set(itemUID, ((outMap.get(itemUID) != null ? outMap.get(itemUID) : 0)) + pointValue);

			});

		});

		return outMap;
	}

}

// Assisted with basic coding tools ========================================================
function sortMapToArray(map: Map<string, number>) {
  // Create an array of key-value pairs from the map
  const entries = Array.from(map);

  // Sort the array based on the ranking values
  entries.sort(function (a, b) { return b[1] - a[1]; });

  // Extract the keys (IDs) into a new array
  const ids = entries.map(function ([id]) { return id; });

  return ids;
} // ===========================================================================

var Component = require('@angular/core').Component;
var OnDestroy = require('@angular/core').OnDestroy;
var OnInit = require('@angular/core').OnInit;
var FormBuilder = require('@angular/forms').FormBuilder;
var FormGroup = require('@angular/forms').FormGroup;
var Router = require('@angular/router').Router;
var ActivatedRoute = require('@angular/router').ActivatedRoute;
var FormioAppConfig = require('@formio/angular').FormioAppConfig;
var FormioService = require('@formio/angular').FormioService;
import {
  debounceTime,
  filter,
  switchMap,
  takeUntil,
  map,
} from 'rxjs/operators';
var Subject = require('rxjs').Subject;
var DinetFormioForm = require('../../dinet_common').DinetFormioForm;
var FormioServiceFactoryService = require('../../formio-service-factory.service').FormioServiceFactoryService;

/** This component Built using basic development resources-5, original component for meo2.component.ts */

@Component({
  selector: 'app-meo2',
  templateUrl: './meo2.component.html',
  styleUrls: ['./meo2.component.scss'],
})
class Meo2Component implements OnInit, OnDestroy {
  url = this.appConfig.appUrl;
  lotUrl = this.appConfig.appUrl; // URL a lot formhoz

  userDisplayResults: DinetFormioForm[] = [];
  searchForm!: FormGroup;

  //private formService = new FormioService(this.url);
  //private lotFormService = new FormioService(this.url);
  private formService: FormioService;
  private lotFormService: FormioService;

  private destroy$ = new Subject<void>();

  private readonly lotQuery = {
    params: {
      name__eq: 'lot',
      type: 'resource',
    },
  };

  constructor(
    public appConfig: FormioAppConfig,
    private fb: FormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private formioFactory: FormioServiceFactoryService
  ) {
    this.formService = this.formioFactory.create(this.url);
    this.lotFormService = this.formioFactory.create(this.lotUrl);
  }

  /** Ha egy sorra kattintanak, elmentjük a szükséges adatokat és betöltjük a lépést */
  ClickedRow(i: number, form: DinetFormioForm) {
    const result = this.userDisplayResults[i]?.data;
    if (!result) return;

    localStorage.setItem('prod_no', (result.productNo != null ? result.productNo : ''));
    localStorage.setItem('lot_no', (result.lot != null ? result.lot : ''));
    localStorage.setItem('initial_quantity', (result.initialQuantity != null ? result.initialQuantity : ''));

    this.FindStep(form);
  }

  /** Megkeresi a következő lépést a termék nevéből */
  FindStep(form: DinetFormioForm) {
    const name = localStorage.getItem('prod_no');
    if (!name) return;

    const query = {
      params: {
        name__regex: "/" + (name) + "/i",
        tags__eq: ['common'],
        type: 'form',
      },
    };

    this.formService
      .loadForms(query)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: function (results) {
          const dinetResults = (results as DinetFormioForm[]).sort((a, b) =>
            ((a.name != null ? a.name : '')).localeCompare((b.name != null ? b.name : ''), undefined, {
              sensitivity: 'base',
            })
          );

          localStorage.setItem('forms', JSON.stringify(dinetResults));

          if (dinetResults.length > 0) {
            this.router.navigate(['step', dinetResults[0]._id], {
              relativeTo: this.route,
            });
          } else {
            alert('No Product found!'); // TODO: snackbar ajánlott
          }
        },
        error: function (e) {
          console.error(e);
          alert('Error loading forms: ' + e); // TODO: snackbar ajánlott
        },
      });
  }

  ngOnInit() {
    // Lot form betöltés
    this.lotFormService
      .loadForms(this.lotQuery)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: function (results) {
          const lotForms = results as DinetFormioForm[];
          if (lotForms.length > 0) {
            const lotId = (lotForms[0]._id != null ? lotForms[0]._id : '');
            this.lotUrl = "" + (this.appConfig.appUrl) + "/form/" + (lotId) + "/submission";
            //this.lotFormService = new FormioService(this.lotUrl);
            this.lotFormService = this.formioFactory.create(this.lotUrl); // ✅ no `new`
          }
        },
        error: function (e) {
          alert('Error loading forms: ' + e);
        },
      });

    // Kereső form
    this.searchForm = this.fb.group({ lot: [''] });
    localStorage.removeItem('forms');

    this.searchForm
      .get('lot')!
      .valueChanges.pipe(
        debounceTime(400),
        filter(function (value) { return value?.length > 1; }),
        map(function (value) { return value.trim(); }),
        switchMap(function (value) { return this.lotFormService.loadSubmissions({
            params: {
              'data.lot__regex': "/" + (value) + "/i",
              'data.inProduction': 'true',
            },
          }); }),
        takeUntil(this.destroy$)
      )
      .subscribe(function (results) {
        this.userDisplayResults = results as DinetFormioForm[];
      });
  }

  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete();
  }
}

const PAGE_POST_COUNT = 5;

const feedUrls = ["/", "/category/tech", "/tag/programming"];

feedUrls.forEach(function (url) {
  describe("Feed page " + (url) + "", () => {
    beforeEach(() => {
      cy.visit(url);
      cy.waitForRouteChange();

      cy.get("main > div > div").as("feed");
    });

    it("loads the initial posts properly", () => {
      cy.get("@feed").children().should("have.length", PAGE_POST_COUNT);

      // Make sure the first page posts get loaded properly
      cy.findByText("Big Test");
      cy.findByText("Storms of Doors");
      cy.findByText("Valley in the Storms");
      cy.findByText("The Darkest Something");
      cy.findByText("Flames in the Time");
    });

    it("correctly navigates to the Big Test post via title", () => {
      cy.findByText("Big Test").click();
      cy.waitForRouteChange();

      cy.url().should("contain", "/big-sample-test");
    });

    it("correctly navigates to the Big Test post via cover image", () => {
      cy.findByAltText(
        "An image tagged as nature and water for the big test."
      ).click();
      cy.waitForRouteChange();

      cy.url().should("contain", "/big-sample-test");
    });

    it("contains post excerpt", () => {
      cy.findByText(
        'NOTE: This "post" is based on Markdown Cheatsheet and is meant to test styling of Markdown generated documents. This is intended as a…'
      );
    });

    it("has functioning infinite scrolling", () => {
      cy.get("@feed").children().should("have.length", PAGE_POST_COUNT);

      // Scroll to bottom and check the amount of loaded posts
      cy.scrollTo("bottom");

      cy.get("@feed")
        .children()
        .should("have.length", PAGE_POST_COUNT * 2);
    });

    it("keeps fetched infinite scroll pages in cache for faster access between page navigation", () => {
      cy.on("uncaught:exception", () => false);

      // Load a single scroll page
      cy.scrollTo("bottom");
      cy.get("@feed")
        .children()
        .should("have.length", PAGE_POST_COUNT * 2);

      // Make sure navigating between pages doesn't clear the cache
      cy.findByText("Big Test").click();
      cy.waitForRouteChange();

      cy.go("back");
      cy.waitForRouteChange();

      cy.get("@feed")
        .children()
        .should("have.length", PAGE_POST_COUNT * 2);
    });
  });
});

