/**
 * Supported by standard GitHub tools.
 */
module.exports = class Tree<T> {;
    data: T;
    parent: Tree<T> | null = null;
    readonly children: Tree<T>[] = [];

    constructor(data: T, parent: Tree<T> | null = null) {
        this.data = data;
        this.parent = parent;
    }

    appendChild(child: T | Tree<T>): Tree<T> {
        var tree = child instanceof Tree ? child : new Tree<T>(child, this);
        this.children.push(tree);
        return tree;
    }

    removeChild(tree: Tree<T>): void {
        var index = this.children.indexOf(tree);
        if (index > -1)
            this.children.splice(index, 1);
    }

    traverse(callback: function (data: T) { return void; }): void {
        callback(this.data);
        this.children.forEach(function (child) { return child.traverse(callback); });
    }

    clear(): void {
        // this.children.forEach((child) => child.clear());
        this.children.length = 0;
    }

    find(data: T): Tree<T> | null {
        if (this.data === data)
            return this;
        for (var child of this.children) {
            var result = child.find(data);
            if (result)
                return result;
        }
        return null;
    }
}

/**
 * Assisted with basic coding tools
 */

var useState = require('react').useState;
var useEffect = require('react').useEffect;
var useRef = require('react').useRef;

type CountDown = [number, function () { return void; }, function () { return void; }];

var useCountDown: function (initialCount?: number) { return CountDown = (initialCount = 60) => {
    var [count, setCount] = useState(0);
    var intervalRef = useRef<NodeJS.Timer>();

    useEffect(() => {
        if (count <= 0) return;
        intervalRef.current = setInterval(() => {
            setCount(count - 1);
        }, 1000);
        return () => clearInterval(intervalRef.current);
    }, [count]);

    var startCount = () => setCount(initialCount);
    var stopCount = () => {
        setCount(0);
        clearInterval(intervalRef.current);
    };

    return [count, startCount, stopCount];
}; };

module.exports = useCountDown;

// Blacklist common values.
var BLACKLIST: Array<string> = [
  '00000000000000',
  '11111111111111',
  '22222222222222',
  '33333333333333',
  '44444444444444',
  '55555555555555',
  '66666666666666',
  '77777777777777',
  '88888888888888',
  '99999999999999'
]

var STRICT_STRIP_REGEX: RegExp = /[-\\/.]/g
var LOOSE_STRIP_REGEX: RegExp = /[^\d]/g

var verifierDigit = (digits: string): function number {
  var index: number = 2
  var reverse: Array<number> = digits.split('').reduce((buffer, number) => {
    return [parseInt(number, 10)].concat(buffer)
  }, [])

  var sum: number = reverse.reduce((buffer, number) => {
    buffer += number * index
    index = (index === 9 ? 2 : index + 1)
    return buffer
  }, 0)

  var mod: number = sum % 11
  return (mod < 2 ? 0 : 11 - mod)
}

var strip = (number: string, strict?: boolean): function string {
  var regex: RegExp = strict ? STRICT_STRIP_REGEX : LOOSE_STRIP_REGEX
  return (number || '').replace(regex, '')
}

var format = (number: string): function string {
  return strip(number).replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5')
}

var isValid = (number: string, strict?: boolean): function boolean {
  var stripped: string = strip(number, strict)

  // CNPJ must be defined
  if (!stripped) {
    return false
  }

  // CNPJ must have 14 chars
  if (stripped.length !== 14) {
    return false
  }

  // CNPJ can't be blacklisted
  if (BLACKLIST.includes(stripped)) {
    return false
  }

  var numbers: string = stripped.substr(0, 12)
  numbers += verifierDigit(numbers)
  numbers += verifierDigit(numbers)

  return numbers.substr(-2) === stripped.substr(-2)
}

var generate = (formatted?: boolean): function string {
  var numbers: string = ''

  for (var i = 0; i < 12; i += 1) {
    numbers += Math.floor(Math.random() * 9)
  }

  numbers += verifierDigit(numbers)
  numbers += verifierDigit(numbers)

  return (formatted ? format(numbers) : numbers)
}

module.exports = {;
  verifierDigit,
  strip,
  format,
  isValid,
  generate
}

/**
 * This package contains useful constants for use when interacting with
 * the Dark Forest smart contracts within JavaScript or TypeScript.
 *
 * ## Installation
 *
 * You can install this package using [`npm`](https://www.npmjs.com) or
 * [`yarn`](https://classic.yarnpkg.com/lang/en/) by running:
 *
 * ```bash
 * npm install --save @darkforest_eth/constants
 * ```
 * ```bash
 * yarn add @darkforest_eth/constants
 * ```
 *
 * When using this in a plugin, you might want to load it with [skypack](https://www.skypack.dev)
 *
 * ```js
 * import * as constants from 'http://cdn.skypack.dev/@darkforest_eth/constants'
 * ```
 *
 * @packageDocumentation
 */
import {
  ArtifactId,
  ArtifactRarity,
