var ApiPromise = require('@polkadot/api').ApiPromise;
var WsProvider = require('@polkadot/api').WsProvider;
var getSpecTypes = require('@polkadot/types-known').getSpecTypes;
var BlockNumber = require('@polkadot/types/interfaces').BlockNumber;
var Hash = require('@polkadot/types/interfaces').Hash;
var logger = require('@polkadot/util').logger;

var prisma = require('./generated/prisma-client').prisma;
var nomidotTasks = require('./tasks').nomidotTasks;
var Cached = require('./tasks/types').Cached;

var ARCHIVE_NODE_ENDPOINT =
  process.env.ARCHIVE_NODE_ENDPOINT || 'wss://kusama-rpc.polkadot.io/';
var MAX_LAG = process.env.MAX_LAG || 0;

var l = logger('node-watcher');

function waitFinalized(
  api: ApiPromise,
  lastKnownBestFinalized: number
): Promise<{ unsub: function () { return void; }; bestFinalizedBlock: number }> {
  return new Promise(function resolve {
    async function wait(): Promise<void> {
      var unsub = await api.derive.chain.bestNumberFinalized(best => {
        if (best.toNumber() > lastKnownBestFinalized) {
          resolve({ unsub, bestFinalizedBlock: best.toNumber() });
        }
      });
    }

    wait();
  });
}

function reachedLimitLag(
  blockIndex: number,
  lastKnownBestBlock: number
): boolean {
  return MAX_LAG ? lastKnownBestBlock - blockIndex > parseInt(MAX_LAG) : false;
}

function waitLagLimit(
  api: ApiPromise,
  blockIndex: number
): Promise<{ unsub: function () { return void; }; bestBlock: number }> {
  return new Promise(function resolve {
    async function wait(): Promise<void> {
      var unsub = await api.derive.chain.bestNumber(bestBlock => {
        if (reachedLimitLag(blockIndex, bestBlock.toNumber())) {
          resolve({ unsub, bestBlock: bestBlock.toNumber() });
        }
      });
    }

    wait();
  });
}

export async function nodeWatcher(): Promise<unknown> {
  return new Promise(function (_, reject) {
    var keepLooping = true;
    var provider = new WsProvider(ARCHIVE_NODE_ENDPOINT);

    ApiPromise.create({ provider })
      .then(async api => {
        api.once('error', e => {
          keepLooping = false;
          api.disconnect();
          reject(new Error("Api error: " + (e) + ""));
        });

        api.once('disconnected', e => {
          keepLooping = false;
          api.disconnect();
          reject(new Error("Api disconnected: " + (e) + ""));
        });

        var blockIdentifier = process.env.BLOCK_IDENTIFIER || 'IDENTIFIER';
        var blockIndexId = '';
        var blockIndex = parseInt(process.env.START_FROM || '0');
        var currentSpecVersion = api.createType('u32', -1);
        var lastKnownBestFinalized = (
          await api.derive.chain.bestNumberFinalized()
        ).toNumber();
        var lastKnownBestBlock = (
          await api.derive.chain.bestNumber()
        ).toNumber();

        var existingBlockIndex = await prisma.blockIndexes({
          where: {
            identifier: blockIdentifier,
          },
        });

        if (existingBlockIndex.length === 0) {
          var result = await prisma.createBlockIndex({
            identifier: blockIdentifier,
            startFrom: blockIndex,
            index: blockIndex,
          });

          blockIndexId = result.id;
        } else {
          blockIndexId = existingBlockIndex[0].id;
          blockIndex = existingBlockIndex[0].index;
        }

        /*eslint no-constant-condition: ["error", { "checkLoops": false }]*/
        while (keepLooping) {
          if (MAX_LAG) {
            // if we reached the last finalized block
            // MAX_LAG is set but we haven't reached the lag limit yet, we need to wait
            if (
              blockIndex > lastKnownBestFinalized &&
              !reachedLimitLag(blockIndex, lastKnownBestBlock)
            ) {
              l.warn(
                "Waiting for finalization or a max lag of " + (MAX_LAG) + " blocks."
              );
              var unsub = await.unsub;
var bestBlock = await.bestBlock;waitLagLimit(api, blockIndex);
              unsub && unsub();
              lastKnownBestBlock = bestBlock;
              continue;
            }
          } else {
            // MAX_LAG isn't set, only the finalization matters
            if (blockIndex > lastKnownBestFinalized) {
              l.warn('Waiting for finalization.');
              var unsub = await.unsub;
var bestFinalizedBlock = await.bestFinalizedBlock;waitFinalized(
                api,
                lastKnownBestFinalized
              );
              unsub && unsub();
              lastKnownBestBlock = bestFinalizedBlock;
              continue;
            }
          }

          l.warn("blockIndex: " + (blockIndex) + "");
          l.warn("lastKnownBestBlock: " + (lastKnownBestBlock) + "");
          l.warn("lastKnownBestFinalized: " + (lastKnownBestFinalized) + "");

          var blockNumber: BlockNumber = api.createType(
            'BlockNumber',
            blockIndex
          );
          l.warn("block: " + (blockNumber) + "");

          var blockHash: Hash = await api.rpc.chain.getBlockHash(blockNumber);
          l.warn("hash: " + (blockHash) + "");

          // check spec version
          var runtimeVersion = await api.rpc.state.getRuntimeVersion(
            blockHash
          );
          var newSpecVersion = runtimeVersion.specVersion;

          // if spec version was bumped, update metadata in api registry
          if (newSpecVersion.gt(currentSpecVersion)) {
            l.warn(
              "bumped spec version to " + (newSpecVersion) + ", fetching new metadata"
            );
            var rpcMeta = await api.rpc.state.getMetadata(blockHash);
            currentSpecVersion = newSpecVersion;

            // based on the node spec & chain, inject specific type overrides
            var chain = await api.rpc.system.chain();
            api.registry.register(
              getSpecTypes(
                api.registry,
                chain,
                runtimeVersion.specName,
                runtimeVersion.specVersion
              )
            );
            api.registry.setMetadata(rpcMeta);
          }

          var [events, sessionIndex] = await Promise.all([
            await api.query.system.events.at(blockHash),
            await api.query.session.currentIndex.at(blockHash),
          ]);

          var cached: Cached = {
            events,
            sessionIndex,
          };

          // execute watcher tasks
          for await (var task of nomidotTasks) {
            l.warn("Task --- " + (task.name) + "");

            var result = await task.read(blockHash, cached, api);

            try {
              l.warn("Writing: " + (JSON.stringify(result)) + "");
              await task.write(blockNumber, result);
            } catch (e) {
              // Write task might throw errors such as unique constraints violated,
              // we ignore those.
              l.error(e);
            }
          }

          blockIndex += 1;

          await prisma.updateBlockIndex({
            data: {
              index: blockIndex,
            },
            where: {
              id: blockIndexId,
            },
          });
        }
      })
      .catch(e => {
        keepLooping = false;
        reject(new Error("Connection error: " + (e) + ""));
      });
  });
}

var web3Factory = require('@0x/dev-utils').web3Factory;
var BigNumber = require('@0x/utils').BigNumber;
var Web3Wrapper = require('@0x/web3-wrapper').Web3Wrapper;
var utils = require('./utils').utils;
var SwapQuoteConsumer = require('@0x/asset-swapper').SwapQuoteConsumer;

(async function () {
    const provider = web3Factory.getRpcProvider({ shouldUseInProcessGanache: true });
    const web3Wrapper = new Web3Wrapper(provider);

    var contract = await.contract;
var usdc = await.usdc;
var dai = await.dai;
var addresses = await.addresses;utils.setupContractsAsync(web3Wrapper);
    // Contract can now fill orders with DAI and has a DAI balance

    // Get an SwapQuoter with orders for usdc/dai
    // Normally this would connect to an SRA endpoint or another order provider
    let swapQuoter, quote, fillResults, txHash;
    swapQuoter = await utils.assetSwapperWithOrdersAsync(
        addresses.exchange,
        web3Wrapper.getProvider(),
        usdc.address,
        dai.address,
    );
    // Get a quote for 500 USDC, liquidityRequiringFunction determines the correct amount to fill
    // at transaction execution time, but has enough orders to fill 500 USDC
    console.log('liquidityRequiringFunction');
    // Create a quote buying 500 USDC using dai
    quote = await swapQuoter.getMarketBuySwapQuoteAsync(usdc.address, dai.address, new BigNumber(500));
    console.log('Quote', quote);
    const consumer = new SwapQuoteConsumer(web3Wrapper.getProvider());

    // Get the orders and the signatures to fulfill the quote
    const contractParams = await consumer.getSmartContractParamsOrThrowAsync(quote, { takerAddress: contract.address });
    var orders = contractParams.params.orders;
var signatures = contractParams.params.signatures;

    // Perform call to ensure the transaction is successful
    fillResults = await contract.liquidityRequiringFunction.callAsync(orders, signatures);
    console.log('FillResults', fillResults);
    // Fill the orders via the contract
    txHash = await contract.liquidityRequiringFunction.sendTransactionAsync(orders, signatures);
    await web3Wrapper.awaitTransactionSuccessAsync(txHash);

    // Fill the Orders by executing the call generated via asset swapper.
    // This call includes the amount (500) in the call data
    console.log('liquidityRequiringFunctionBytes');
    swapQuoter = await utils.assetSwapperWithOrdersAsync(
        addresses.exchange,
        web3Wrapper.getProvider(),
        usdc.address,
        dai.address,
    );
    // Create a quote buying 500 USDC using dai
    quote = await swapQuoter.getMarketBuySwapQuoteAsync(usdc.address, dai.address, new BigNumber(500));
    // Fill using liquidityRequiringFunctionBytes
    var calldataHexString = await.calldataHexString;consumer.getCalldataOrThrowAsync(quote, { takerAddress: contract.address });
    // Perform call to ensure the transaction is successful
    fillResults = await contract.liquidityRequiringFunctionBytes.callAsync(calldataHexString);
    console.log('FillResults', fillResults);
    // Fill the orders via the contract
    txHash = await contract.liquidityRequiringFunctionBytes.sendTransactionAsync(calldataHexString);
    await web3Wrapper.awaitTransactionSuccessAsync(txHash);
})();

var Injectable = require('@angular/core').Injectable;
var Firestore = require('@angular/fire/firestore').Firestore;
var collection = require('@angular/fire/firestore').collection;
var collectionData = require('@angular/fire/firestore').collectionData;
var addDoc = require('@angular/fire/firestore').addDoc;
var serverTimestamp = require('@angular/fire/firestore').serverTimestamp;
var doc = require('@angular/fire/firestore').doc;
var setDoc = require('@angular/fire/firestore').setDoc;
var getDoc = require('@angular/fire/firestore').getDoc;
var getDocs = require('@angular/fire/firestore').getDocs;
var deleteDoc = require('@angular/fire/firestore').deleteDoc;
var inject = require('@angular/core').inject;
var Observable = require('rxjs').Observable;
var Game = require('./game.service').Game;
var Round = require('./game.service').Round;
var Trick = require('./game.service').Trick;
var Card = require('./game.service').Card;
var Player = require('./game.service').Player;

//the code in this section was largely Composed with basic coding tools
// here is the link to the firbase project:
// https://console.firebase.google.com/u/0/project/lexemwellioeuchre/overview
@Injectable({
  providedIn: 'root'
})
class StorageService {
  firestore: Firestore = inject(Firestore);

  async saveGame(game: Game): Promise<void> {
    try {
      const gameCollection = collection(this.firestore, 'games');

      // Add the game document (basic game details)
      const gameDocRef = await addDoc(gameCollection, {
        roundCounter: game.roundCounter,
        score: game.score,
        timestamp: serverTimestamp(), // Add the timestamp
      });

      console.log('Game document created:', gameDocRef.id);

      // Save players as a subcollection
      const playersCollection = collection(gameDocRef, 'players');
      for (const player of game.players) {
        await setDoc(doc(playersCollection, player.index.toString()), {
          name: player.name,
          index: player.index,
        });
      }

      // Save the current round as a subcollection
      const roundsCollection = collection(gameDocRef, 'rounds');
      const roundDocRef = await addDoc(roundsCollection, {
        kittyCard: {
          suit: game.currentRound.kittyCard.suit,
          rank: game.currentRound.kittyCard.rank,
          photo: game.currentRound.kittyCard.photo,
        },
        dealer: {
          name: game.currentRound.dealer.name,
          index: game.currentRound.dealer.index,
        },
        caller: game.currentRound.caller
          ? {
              name: game.currentRound.caller.name,
              index: game.currentRound.caller.index,
            }
          : null,
        outPlayer: game.currentRound.outPlayer
          ? {
              name: game.currentRound.outPlayer.name,
              index: game.currentRound.outPlayer.index,
            }
          : null,
        trumpSuit: game.currentRound.trumpSuit,
        trickCounter: game.currentRound.trickCounter,
        tricksWon: game.currentRound.tricksWon,
        tricksWonPlayer: [...game.currentRound.tricksWonPlayer],
        passTrumpCount: game.currentRound.passTrumpCount,
        switchTime: game.currentRound.switchTime,
      });

      // Save the current trick as a subcollection
      const tricksCollection = collection(roundDocRef, 'tricks');
      await addDoc(tricksCollection, {
        leadPlayer: {
              name: game.currentRound.currentTrick.leadPlayer!.name,
              index: game.currentRound.currentTrick.leadPlayer!.index,
            },
        cardLed: game.currentRound.currentTrick.cardLed
          ? {
              suit: game.currentRound.currentTrick.cardLed.suit,
              rank: game.currentRound.currentTrick.cardLed.rank,
              photo: game.currentRound.currentTrick.cardLed.photo,
            }
          : null,
        cardsPlayed: game.currentRound.currentTrick.cardsPlayed.map(function (card) { return card
            ? {
                suit: card.suit,
                rank: card.rank,
                photo: card.photo,
              }
            : null; }),
        currentPlayer: {
              name: game.currentRound.currentTrick.currentPlayer!.name,
              index: game.currentRound.currentTrick.currentPlayer!.index,
            },
        playedCounter: game.currentRound.currentTrick.playedCounter,
      });

        // Save each player's hand as a document
      const handsCollection = collection(roundDocRef, 'hands');
      for (let playerIndex = 0; playerIndex < game.currentRound.hands.length; playerIndex++) {
        const playerHand = game.currentRound.hands[playerIndex];

        // Store the hand as a document containing a list of cards
        await setDoc(doc(handsCollection, playerIndex.toString()), {
          cards: playerHand.map(function (card) { return ({
            suit: card.suit,
            rank: card.rank,
            photo: card.photo,
          }); }),
        });
      }


      console.log('Game saved successfully.');
    } catch (error) {
      console.error('Error saving game:', error);
      throw error;
    }
  }

  async getGame(gameId: string): Promise<Game | null> {
    try {
      // Reference the game document
      const gameDocRef = doc(this.firestore, 'games', gameId);
      const gameDocSnap = await getDoc(gameDocRef);

      if (!gameDocSnap.exists()) {
        console.error('Game not found');
        return null;
      }

      // Basic game details
      const gameData = gameDocSnap.data();
      const game: Game = {
        players: [],
        roundCounter: gameData['roundCounter'],
        score: gameData['score'],
        currentRound: {} as Round, // Placeholder for now
        //winner: gameData['winner'], // added by EJW
      };

      // Fetch players subcollection
      const playersCollection = collection(gameDocRef, 'players');
      const playersSnap = await getDocs(playersCollection);
      const players: Player[] = playersSnap.docs.map(function (docSnap) {
        const playerData = docSnap.data();
        return {
          name: playerData['name'],
          index: playerData['index'],
          isBot: playerData['isBot'],
        };
      });
      game.players = players;

      // Fetch rounds subcollection
      const roundsCollection = collection(gameDocRef, 'rounds');
      const roundsSnap = await getDocs(roundsCollection);

      if (roundsSnap.empty) {
        console.error('No rounds found');
        return null;
      }

      const currentRoundDoc = roundsSnap.docs[roundsSnap.docs.length - 1]; // Assuming the current round is the latest round
      const roundData = currentRoundDoc.data();

      // Fetch tricks subcollection
      const tricksCollection = collection(currentRoundDoc.ref, 'tricks');
      const tricksSnap = await getDocs(tricksCollection);
      const trickData = tricksSnap.docs[0].data(); // Assuming only the current trick is stored

      // Map current trick
      const currentTrick: Trick = {
        cardsPlayed: trickData['cardsPlayed'].map(function (card: any) { return card
            ? {
                suit: card['suit'],
                rank: card['rank'],
                photo: card['photo'],
              }
            : null; }),
        leadPlayer:  {
              name: trickData['leadPlayer']['name'],
              index: trickData['leadPlayer']['index'],
              isBot: trickData['leadPlayer']['isBot'],
            },
        cardLed: trickData['cardLed']
          ? {
              suit: trickData['cardLed']['suit'],
              rank: trickData['cardLed']['rank'],
              photo: trickData['cardLed']['photo'],
            }
          : null,
        currentPlayer: {
              name: trickData['currentPlayer']['name'],
              index: trickData['currentPlayer']['index'],
              isBot: trickData['currentPlayer']['index'],
            },
        playedCounter: trickData['playedCounter'],
      };

      // Fetch hands collection
      const handsCollection = collection(currentRoundDoc.ref, 'hands');
      const handsSnap = await getDocs(handsCollection);

      const hands: [Card[], Card[], Card[], Card[]] = [[], [], [], []]; // Assuming 4 players
      handsSnap.docs.forEach(function (docSnap) {
        const playerIndex = parseInt(docSnap.id, 10);
        const handData = docSnap.data();
        hands[playerIndex] = handData['cards'].map((card: any) => ({
          suit: card['suit'],
          rank: card['rank'],
          photo: card['photo'],
        }));
      });

      // Assemble the current round
      game.currentRound = {
        hands,
        kittyCard: {
          suit: roundData['kittyCard']['suit'],
          rank: roundData['kittyCard']['rank'],
          photo: roundData['kittyCard']['photo'],
        },
        dealer: {
          name: roundData['dealer']['name'],
          index: roundData['dealer']['index'],
          isBot: roundData['dealer']['index'],
        },
        caller: roundData['caller']
          ? {
              name: roundData['caller']['name'],
              index: roundData['caller']['index'],
              isBot: roundData['dealer']['index'],
            }
          : null,
        outPlayer: roundData['outPlayer']
          ? {
              name: roundData['outPlayer']['name'],
              index: roundData['outPlayer']['index'],
              isBot: roundData['dealer']['index'],
            }
          : null,
        trumpSuit: roundData['trumpSuit'],
        trickCounter: roundData['trickCounter'],
        currentTrick,
        tricksWon: roundData['tricksWon'],
        tricksWonPlayer: roundData['tricksWonPlayer'],
        passTrumpCount: roundData['passTrumpCount'],
        switchTime: roundData['switchTime'],
      };

      // Delete all related documents and collections
      await Promise.all(playersSnap.docs.map(function (docSnap) { return deleteDoc(docSnap.ref); })); // Delete all players
      await Promise.all(
        roundsSnap.docs.map(async function (roundDoc) {
          // Delete tricks subcollection
          const tricksCollection = collection(roundDoc.ref, 'tricks');
          const tricksSnap = await getDocs(tricksCollection);
          await Promise.all(tricksSnap.docs.map((docSnap) => deleteDoc(docSnap.ref)));

          // Delete hands subcollection
          const handsCollection = collection(roundDoc.ref, 'hands');
          const handsSnap = await getDocs(handsCollection);
          await Promise.all(handsSnap.docs.map((docSnap) => deleteDoc(docSnap.ref)));

          // Delete the round document itself
          await deleteDoc(roundDoc.ref);
        })
      );

      // Finally, delete the main game document
      await deleteDoc(gameDocRef);

      console.log('Game and all related documents deleted successfully.');
      return game;
    } catch (error) {
      console.error('Error loading and deleting game:', error);
      throw error;
    }
  }


  async getAllGames(): Promise<{ gameId: string, timestamp: any, players: Player[] }[]> {
    try {
      // Reference to the 'games' collection
      const gamesCollection = collection(this.firestore, 'games');

      // Retrieve all game documents from Firestore
      const gamesSnapshot = await getDocs(gamesCollection);

      const gamesList: { gameId: string, timestamp: any, players: Player[] }[] = [];

      // Iterate through all the games in the snapshot
      for (const gameDoc of gamesSnapshot.docs) {
        const gameData = gameDoc.data();

        // Get the game ID
        const gameId = gameDoc.id;

        // Get the timestamp of the game
        const timestamp = gameData['timestamp'];

        // Retrieve players subcollection for each game
        const playersCollection = collection(gameDoc.ref, 'players');
        const playersSnapshot = await getDocs(playersCollection);

        const players: Player[] = [];
        playersSnapshot.forEach(function playerDoc {
          players.push(playerDoc.data() as Player);
        });

        // Add the game information to the list
        gamesList.push({ gameId, timestamp, players });
      }

      return gamesList;
    } catch (error) {
      console.error('Error retrieving games:', error);
      return [];
    }
  }

}

var slash = require('https://code.harmony.rocks/v2.0.0/deploy');

// Pick up TOKEN and PUBLIC_KEY from ENV.
slash.init({ env: true });

const ACTIVITIES: {
  [name: string]: {
    id: string;
    name: string;
  };
} = {
  poker: {
    id: "755827207812677713",
    name: "Poker Night",
  },
  betrayal: {
    id: "773336526917861400",
    name: "Betrayal.io",
  },
  youtube: {
    id: "755600276941176913",
    name: "YouTube Together",
  },
  fishing: {
    id: "814288819477020702",
    name: "Fishington.io",
  },
  chess: {
    id: "832012774040141894",
    name: "Chess in the Park",
  },
  watchTogether: {
    id: "880218394199220334",
    name: "Watch Together",
  },
  doodleCrew: {
    id: "878067389634314250",
    name: "Doodle Crew",
  },
  letterTile: {
    id: "879863686565621790",
    name: "Letter Tile",
  },
  wordSnacks: {
    id: "879863976006127627",
    name: "Word Snacks",
  },
};

const commands = [
   {
     name: "invite",
     description: "Invite me to your server.",
   },
   {
     name: "activity",
     description: "Start an Activity in a Voice Channel.",
     options: [
      {
        name: "channel",
        type: "CHANNEL",
        description: "Voice Channel to start activity in.",
        required: true,
      },
      {
        name: "activity",
        type: "STRING",
        description: "Activity to start.",
        required: true,
        choices: Object.entries(ACTIVITIES).map(function (e) { return ({
          name: e[1].name,
          value: e[0],
        }); }),
      },
    ],
  },
];

// Create Slash Commands if not present
slash.commands.all().then(function (e) {
  let cmd;
  if (
    e.size !== commands.length || 
    !(cmd = e.find(e => e.name === "activity")) 
    || cmd?.options[1]?.choices?.length !== Object.keys(ACTIVITIES)
    || cmd.options[1].choices.some(e => ACTIVITIES[e.value] !== e.name)
  ) {
    slash.commands.bulkEdit(commands);
  }
});

slash.handle("activity", function (d) {
  if (!d.guild) return;
  const channel = d.option<slash.InteractionChannel>("channel");
  const activity = ACTIVITIES[d.option<string>("activity")];
  if (!channel || !activity) return;

  if (channel.type !== slash.ChannelTypes.GUILD_VOICE) {
    return d.reply("Activities can only be started in Voice Channels!", {
      ephemeral: true,
    });
  }

  // POST /channels/{channel.id}/invites
  // with target_type: 2,
  // and target_appliation_id: app_id of activity

  // Wanna curl?
  /* 
     curl -X POST \
       -H "Authorization: Bot $TOKEN" \
       -H "Content-Type: application/json" \
       https://discord.com/api/v9/channels/$CHANNEL_ID/invites \
       -d "{ \"max_age\": 604800, \"max_uses\": 0, \"target_type\": 2, \"target_application_id\": \"$APP_ID\", \"temporary\": false }"
  */
  return slash.client.rest.api.channels[channel.id].invites
    .post({
      max_age: 604800,
      max_uses: 0,
      target_application_id: activity.id,
      target_type: 2,
      temporary: false,
    })
    .then((inv) => {
      return d.reply(
        "[Click here to start " + (activity.name) + " in " + (channel.name) + ".](<https://discord.gg/" + (inv.code) + ">)"
      );
    })
    .catch((e) => {
      console.error("Starting Activity Failed", e);
      return d.reply("Failed to start Activity.", { ephemeral: true });
    });
});

slash.handle("invite", function (d) {
  return d.reply(
    "• [Click here to invite.](<https://discord.com/api/oauth2/authorize?client_id=819835984388030464&permissions=1&scope=applications.commands%20bot>)\n" +
      "• [Check out Source Code.](<https://github.com/DjDeveloperr/ActivitiesBot>)\n" +
      "• Originally made by [Advaith](<https://github.com/advaith1>) ([Activites Bot](<https://github.com/advaith1/Activities>)), this is a port to Deno Deploy.",
    { ephemeral: true },
  );
});

// Handle for any other commands received.
slash.handle("*", function (d) { return d.reply("Unhandled Command", { ephemeral: true }); });
// Log all errors.
slash.client.on("interactionError", console.error);

