var initHelpButton = require('./initHelpButton');
var initSongSelector = require('./initSongSelector');
var initWaveformSelector = require('./initWaveformSelector');
require('./style.css');

type ValidFFTSizeStringType = '2048' | '1024' | '512';

const audioElement = document.querySelector('audio');
const html = document.querySelector('html');
const canvas = document.querySelector('canvas');
const overlayControls = document.querySelector('.overlay-controls');
const canvasContext = canvas?.getContext('2d');
const FFT_SIZE_TO_RADIUS_MAP = {
  '2048': Math.floor(((2048 / 2) / Math.PI) - 80),
  '1024': Math.floor(((1024 / 2) / Math.PI) - 80),
  '512': Math.floor(((512 / 2) / Math.PI) - 80)
};
const FFT_SIZE_TO_WAVE_HEIGHT_MAP = {
  '2048': 0.5,
  '1024': 0.4,
  '512': 0.3
}
const MIN_FFT_SIZE = 512;

let WIDTH = 1280;
let HEIGHT = 320;
let FFT_SIZE = 2048;
let isNotAPlayPauseTouch = false;
let currentAudioURL = '';
let currentWaveform = 'sinewave'
let previousTouch: (undefined | Touch);
let audioContext: (undefined | null | AudioContext),
  gainNode: (undefined | GainNode),
  mediaElementNode: (undefined | MediaElementAudioSourceNode),
  analyserNode: (undefined | AnalyserNode),
  animationCancelId: (undefined | number);

if (audioElement) {
  audioElement.src = currentAudioURL;
}

/* SETUP */
const setupAudioContext = function () {

  if (!audioElement) {
    return null;
  }

  audioContext = new AudioContext();
  mediaElementNode = audioContext.createMediaElementSource(audioElement);
  gainNode = audioContext.createGain();
  analyserNode = audioContext.createAnalyser();

  gainNode.gain.value = 1;

  if (audioContext.state === 'suspended') {
    audioContext.resume();
  }

  // Do not forget to connect the node to a destination
  mediaElementNode.connect(analyserNode);
  analyserNode.connect(gainNode);
  gainNode.connect(audioContext.destination);
};

/* ANIMATION OPERATIONS */

const drawSineWave = function () {
  if (!analyserNode || !canvas || !canvasContext) {
    return;
  }

  animationCancelId = requestAnimationFrame(drawSineWave);

  analyserNode.fftSize = FFT_SIZE;
  const byteTimeDomainData = new Uint8Array(analyserNode.fftSize);
  analyserNode.getByteTimeDomainData(byteTimeDomainData);

  canvasContext.fillStyle = 'black';
  canvasContext.fillRect(0, 0, WIDTH, HEIGHT);
  canvasContext.strokeStyle = 'white';

  const xAxisSeparation = WIDTH / (analyserNode.fftSize);
  const START_Y = HEIGHT / 2 + 128;

  canvasContext.beginPath();
  // canvasContext.moveTo(0, START_Y);

  byteTimeDomainData.forEach((value, index) => {
    const x = index * xAxisSeparation;
    const y = START_Y - value;

    canvasContext.lineTo(x, y);
  });

  canvasContext.stroke();
};

// Parts of this code are Adapted from standard coding samples
// Specifically the logic to calculate the angle inside the for loop
// was AI generated. I was trying to use the Mid point circle algorithm
// but the AI used trigonometric method (this is supposed to be slower
// but I was blocked in my approach).
const drawCircle = function () {
  if (!canvas || !canvasContext || !analyserNode) {
    return;
  }

  animationCancelId = requestAnimationFrame(drawCircle);

  const numPoints = FFT_SIZE;
  const centerX = canvas.width / 2;
  const centerY = canvas.height / 2;
  const radius = FFT_SIZE_TO_RADIUS_MAP[('' + numPoints) as ValidFFTSizeStringType];
  const points = [];

  // Clear the screen for the current animation frame
  canvasContext.fillStyle = 'black';
  canvasContext.fillRect(0, 0, canvas.width, canvas.height);

  // Set the stroke style
  canvasContext.strokeStyle = 'white';

  analyserNode.fftSize = FFT_SIZE;
  const byteTimeDomainData = new Uint8Array(analyserNode.fftSize);
  analyserNode.getByteTimeDomainData(byteTimeDomainData);

  for (let i = 0; i < numPoints; i++) {
    // Calculating the angle of a given point by using formula:
    // (index/total) * 360
    // When index/total is 1 i.e index === total, then angle will be
    // 360 degrees.
    let angle = (i / numPoints) * 2 * Math.PI;

    // x = r * cos(theta)
    // Adding byteTimeDomainData[i] to r because we want the point to
    // represent the amplitude of the wave.
    let x = centerX + (radius + byteTimeDomainData[i]) * Math.cos(angle);
    // y = r * sin(theta)
    let y = centerY + (radius + byteTimeDomainData[i]) * Math.sin(angle);

    // Store the points in an array for later access
    points.push({x: x, y: y});
  }

  canvasContext.beginPath();
  for (let i = 0; i < points.length; i++) {
    canvasContext.lineTo(points[i].x, points[i].y);
  }
  canvasContext.stroke();
}

/* AUDIO OPERATIONS */

const playPauseAudio = function () {
  if (!audioElement) {
    return;
  }

  if (!audioContext) {
    setupAudioContext();
  }

  if (audioElement.paused) {
    audioElement.play();
    currentWaveform === 'sinewave' ? drawSineWave() : drawCircle();
  }
  else {
    audioElement.pause();
    animationCancelId !== undefined && cancelAnimationFrame(animationCancelId);
  }
}

const increaseVolume = function (delta = 0.1) {
  const gain = gainNode?.gain;

  if (gain === undefined) {
    return;
  }

  const newValue = gain.value + delta;
  (newValue < 2) && (gain.value = newValue);
}

const decreaseVolume = function (delta = 0.1) {
  const gain = gainNode?.gain;

  if (gain === undefined) {
    return;
  }

  const newValue = gain.value - delta;
  (newValue > 0) && (gain.value = newValue);
}

/* RESIZE HANDLER */
const resizeObserver = new ResizeObserver(function (entries) {
  for (let entry of entries) {
    if (entry.borderBoxSize) {
      WIDTH = entry.borderBoxSize[0].inlineSize;
      HEIGHT = entry.borderBoxSize[0].blockSize;

      if (canvas && canvasContext) {
        canvas.width = WIDTH;
        canvas.height = HEIGHT;

        canvasContext.fillStyle = "black";
        canvasContext.fillRect(0, 0, canvas.width, canvas.height);
      }

      const bestFFTSizeBasedOnWidth = Object.entries(FFT_SIZE_TO_RADIUS_MAP).sort((a, b) => b[1] - a[1]).find(([key, value]) => {
        // @ts-ignore
        return 2 * (value + FFT_SIZE_TO_WAVE_HEIGHT_MAP[key] * 500) < WIDTH
      });

      console.log(bestFFTSizeBasedOnWidth)
      FFT_SIZE = bestFFTSizeBasedOnWidth ? Number.parseInt(bestFFTSizeBasedOnWidth[0]) : MIN_FFT_SIZE;

      currentWaveform === 'sinewave' ? drawSineWave() : drawCircle();

      return;
    }
  }
});


/* EVENT HANDLERS */
const handleKeyDown = function (e: KeyboardEvent) {
  var key = e.key;

  if (!audioContext && !(e.metaKey || e.altKey || e.ctrlKey)) {
    setupAudioContext();
  }

  switch (key) {
    case ' ': {
      playPauseAudio();
      break;
    }

    case 'ArrowUp': {
      increaseVolume();
      break;
    }

    case 'ArrowDown': {
      decreaseVolume();
      break;
    }
  }
}

const handleTouchEnd = function () {
  if (isNotAPlayPauseTouch) {

    // Cleanup
    isNotAPlayPauseTouch = false;
    previousTouch = undefined;
    return;
  }

  playPauseAudio();
}

const handleTouchMove = function (e: TouchEvent) {
  // This is a touch move and not just a touch.
  // i.e. the user wants to increase or decrease their volume.
  // Setting isNotAPlayPauseTouch will ensure that the music does not
  // stop/start playing.
  isNotAPlayPauseTouch = true;

  // There was no previous touch
  // The user has not indicated whether they want to increase or decrease
  // volume. So, we retun.
  if (!previousTouch) {
    return;
  }

  const currentTouch = e.changedTouches[0];

  if (currentTouch.clientY > previousTouch.clientY) {
    decreaseVolume();
  }
  else {
    increaseVolume();
  }

  previousTouch = currentTouch;
}

const handleTouchStart = function (e: TouchEvent) {
  previousTouch = e.changedTouches[0];
}

const songSelectorCallback = function (url: string) {
  if (!audioElement) {
    return;
  }

  audioElement.src = url;
  playPauseAudio();
}

const waveformSelectorCallback = function (option: string) {
  if (!audioElement) {
    return;
  }

  currentWaveform = option;

  typeof animationCancelId === 'number'  && cancelAnimationFrame(animationCancelId);

  currentWaveform === 'sinewave' ? drawSineWave() : drawCircle();
}

/* INITIALIZE OTHER UI ELEMENTS */
initSongSelector(songSelectorCallback);
initWaveformSelector(waveformSelectorCallback);
initHelpButton();

/* REGISTER EVENT LISTENERS */
window.addEventListener('keydown', handleKeyDown);
window.addEventListener('touchstart', handleTouchStart);
window.addEventListener('touchend', handleTouchEnd);
window.addEventListener('touchmove', handleTouchMove);
overlayControls && overlayControls.addEventListener('touchend', function (e) { e.stopPropagation(); });
overlayControls && overlayControls.addEventListener('touchmove', function (e) { e.stopPropagation(); });
resizeObserver.observe(html as HTMLHtmlElement);

import {
  MarkdownPostProcessor,
  MarkdownPostProcessorContext,
  Plugin,
} from "obsidian";

enum TaskType {
  TODO = "TODO",
  DONE = "DONE",
  DOING = "DOING",
  LATER = "LATER",
  CANCELED = "CANCELED",
  UNKNOWN = "UNKNOWN",
}

enum TaskCSSClass {
  COMPLETE = "logseq-complete-task",
  INCOMPLETE = "logseq-incomplete-task",
  KEYWORD = "logseq-keyword",
}

const VERSION = "0.0.4";

class LogSeqRegExes {
  static parseTaskType(content: string): TaskType {
    if (content.startsWith("DONE ")) {
      return TaskType.DONE;
    } else if (content.startsWith("TODO ")) {
      return TaskType.TODO;
    } else if (content.startsWith("DOING ")) {
      return TaskType.DOING;
    } else if (content.startsWith("LATER ")) {
      return TaskType.LATER;
    } else if (content.startsWith("CANCELED ")) {
      return TaskType.CANCELED;
    } else {
      return TaskType.UNKNOWN;
    }
  }

  static HEADING_REGEX = {
    h1: /^(?:\s+)?- # (?:.*)$/gms,
    h2: /^(?:\s+)?- ## (?:.*)$/gms,
    h3: /^(?:\s+)?- ### (?:.*)$/gms,
    h4: /^(?:\s+)?- #### (?:.*)$/gms,
    h5: /^(?:\s+)?- ##### (?:.*)$/gms,
  };

  static HEADING_FORMAT_REGEX = {
    hf1: /^(?:\s+)?- # /gms,
    hf2: /^(?:\s+)?- ## /gms,
    hf3: /^(?:\s+)?- ### /gms,
    hf4: /^(?:\s+)?- #### /gms,
    hf5: /^(?:\s+)?- ##### /gms,
  };

  static BEGIN_BLOCK_REGEX = new RegExp(
    /\#\+BEGIN_(WARNING|IMPORTANT|QUOTE|CAUTION)/gms
  );
  static END_BLOCK_REGEX = new RegExp(
    /\#\+END_(WARNING|IMPORTANT|QUOTE|CAUTION)/gms
  );

  static isBlock(content: string): boolean {
    return LogSeqRegExes.BEGIN_BLOCK_REGEX.test(content);
  }
}

class CodeMirrorOverlays {
  static headingsOverlay = {
    token: function (stream: any) {
      const baseToken = stream.baseToken();
      if (stream.match(LogSeqRegExes.HEADING_REGEX["h1"])) {
        return "header header-1";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h2"])) {
        return "header header-2";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h3"])) {
        return "header header-3";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h4"])) {
        return "header header-4";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h5"])) {
        return "header header-5";
      } else {
        stream.skipToEnd();
      }
    }
  };
  static headingFormatOverlay = {
    token: function (stream: any) {
      const baseToken = stream.baseToken();
      if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf1"])) {
        return "formatting-header formatting-header-1";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf2"])) {
        return "formatting-header formatting-header-2";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf3"])) {
        return "formatting-header formatting-header-3";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf4"])) {
        return "formatting-header formatting-header-4";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf5"])) {
        return "formatting-header formatting-header-5";
      } else {
        stream.skipToEnd();
      }
    }
  };
  static cmAddHeadingOverlay(cm: CodeMirror.Editor) {
    cm.addOverlay(CodeMirrorOverlays.headingsOverlay);
    cm.addOverlay(CodeMirrorOverlays.headingFormatOverlay,{priority:99});
  }

  static cmRemoveHeadingOverlay(cm: CodeMirror.Editor) {
    cm.removeOverlay(CodeMirrorOverlays.headingsOverlay);
    cm.removeOverlay(CodeMirrorOverlays.headingFormatOverlay);
  }
}

function createKeywordElement(keyword: string): HTMLElement {
  const element = document.createElement("span");
  element.classList.add(TaskCSSClass.KEYWORD);
  element.textContent = keyword;
  return element;
}

function createCheckboxElement(checked: boolean = false): HTMLElement {
  const element = document.createElement("input");
  element.type = "checkbox";
  element.checked = checked;
  return element;
}

module.exports = class LogSeqPlugin extends Plugin {;
  static removeProperties(content: string): string {
    return content
      .replace(/doing:: (?:\d{13})/, "")
      .replace(/done:: (?:\d{13})/, "")
      .replace(/todo:: (?:\d{13})/, "")
      .replace(/doing:: (?:\d{13})/, "")
      .replace(/later:: (?:\d{13})/, "")
      .replace(/canceled:: (?:\d{13})/, "")
      .replace(
        /id:: (?:[0-9A-F]{8}-[0-9A-F]{4}-4[0-9A-F]{3}-[89AB][0-9A-F]{3}-[0-9A-F]{12})/i,
        ""
      )
      .replace(/collapsed:: (?:true|false)/gms, "");
  }

  static processChildren(el: Element, keyword: string) {
    el.childNodes.forEach(function (child) {
      if (child.nodeType == Node.TEXT_NODE) {
        if (child.nodeValue.startsWith(keyword)) {
          child.nodeValue = child.nodeValue.replace(keyword, "");
        }
        child.nodeValue = LogSeqPlugin.removeProperties(child.nodeValue);
      }
    });
  }

  static styleNode(el: Element, classname: TaskCSSClass) {
    el.querySelectorAll("li[data-line]").forEach(function (child) {
      // Do not "complete" the child tasks, since this is LogSeq's behaviour
      child.classList.add(TaskCSSClass.INCOMPLETE);
    });
    el.classList.add(classname);
  }

  static postprocessor: MarkdownPostProcessor = function (
    el: HTMLElement,
    ctx: MarkdownPostProcessorContext
  ) {
    const entries = el.querySelectorAll("li[data-line]");

    entries.forEach((entry) => {
      // Check if the entry is a org-mode block
      if (LogSeqRegExes.isBlock(entry.innerHTML)) {
        let replacedBlock = entry.innerHTML.replace(
          LogSeqRegExes.BEGIN_BLOCK_REGEX,
          "<blockquote> &#9759;"
        );
        replacedBlock = replacedBlock.replace(
          LogSeqRegExes.END_BLOCK_REGEX,
          "</blockquote>"
        );
        entry.innerHTML = replacedBlock;
      }
      const taskType = LogSeqRegExes.parseTaskType(entry.textContent);

      if (taskType == TaskType.DONE) {
        LogSeqPlugin.processChildren(entry, TaskType.DONE);

        entry.insertAdjacentElement("afterbegin", createCheckboxElement(true));
        LogSeqPlugin.styleNode(entry, TaskCSSClass.COMPLETE);
      } else if (taskType == TaskType.TODO) {
        LogSeqPlugin.processChildren(entry, TaskType.TODO);

        entry.insertAdjacentElement(
          "afterbegin",
          createKeywordElement(TaskType.TODO)
        );

        entry.insertAdjacentElement("afterbegin", createCheckboxElement());
        LogSeqPlugin.styleNode(entry, TaskCSSClass.INCOMPLETE);
      } else if (taskType == TaskType.DOING) {
        LogSeqPlugin.processChildren(entry, TaskType.DOING);

        entry.insertAdjacentElement(
          "afterbegin",
          createKeywordElement(TaskType.DOING)
        );

        entry.insertAdjacentElement("afterbegin", createCheckboxElement());
      } else if (taskType == TaskType.LATER) {
        LogSeqPlugin.processChildren(entry, TaskType.LATER);

        entry.insertAdjacentElement(
          "afterbegin",
          createKeywordElement(TaskType.LATER)
        );

        entry.insertAdjacentElement("afterbegin", createCheckboxElement());
        LogSeqPlugin.styleNode(entry, TaskCSSClass.INCOMPLETE);
      } else if (taskType == TaskType.CANCELED) {
        LogSeqPlugin.processChildren(entry, TaskType.CANCELED);
        LogSeqPlugin.styleNode(entry, TaskCSSClass.COMPLETE);
      }
    });
  };

  onload() {
    console.log("Loading logseq-compat plugin " + (VERSION) + "");
    this.registerMarkdownPostProcessor(LogSeqPlugin.postprocessor);
    // Style headings in source editing
    this.registerCodeMirror(CodeMirrorOverlays.cmAddHeadingOverlay);
  }

  onunload() {
    console.log("unloading logseq-compat plugin " + (VERSION) + "");
    this.registerCodeMirror(CodeMirrorOverlays.cmRemoveHeadingOverlay);
  }
}

