function generateRandomId(length: number): string {
  const characters =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  let randomId = "";
  for (let i = 0; i < length; i++) {
    randomId += characters.charAt(
      Math.floor(Math.random() * characters.length)
    );
  }
  return randomId;
} // Crafted with basic coding tools

class Todo {
  id: string;
  text: string;

  constructor(todoText: string) {
    this.text = todoText;
    this.id = generateRandomId(10);
  }
}

module.exports = Todo;

var uploadFilesToS3 = require('@/wab/server/util/s3-util').uploadFilesToS3;
var ComponentReference = require('@/wab/server/workers/codegen').ComponentReference;
var LoaderEsbuildFatalError = require('@/wab/shared/ApiErrors/errors').LoaderEsbuildFatalError;
import {
  asyncTimeout,
  ensure,
  mkShortUuid,
  omitNils,
  tuple,
  withoutNils,
} from "@/wab/shared/common";
var Sentry = require('@sentry/node');
var fs = require('fs').promises;
var uniq = require('lodash').uniq;
var uniqBy = require('lodash').uniqBy;
