/**
If some of the components in the build are missing from the bundle, esbuild
will throw an error message that looks like this:

```
Build failed with 1 error:
render__p_qAnx7Cavdb.tsx:69:71: ERROR: Could not resolve "./comp__xeF6Jn1vylil"
```

This means that the component with the uuid `p_qAnx7Cavdb` is trying to import the component with
the uuid `xeF6Jn1vylil`, but that component is missing from the bundle.
 */

// Regex Assisted with basic coding tools 4
const MISSING_COMPONENT_PATTERN =
  /([a-zA-Z0-9]+)__([^:]+)\..*?Could not resolve "\.\/comp__(.*?)"/g;

function projectRefText(ref: ComponentReference) {
  return '"' + (ref.projectName) + '" (ID:' + (ref.projectId) + ")";
}

function buildMissingComponentErrors(
  errors: {
    missingComponent?: ComponentReference;
    importingComponent: ComponentReference;
  }[]
) {
  const projects = uniqBy(
    [
      ...errors.map(function (err) { return err.importingComponent; }),
      ...withoutNils(errors.map(function (err) { return err.missingComponent; })),
    ],
    function (c) { return c.projectId; });
  return "
Found " + (errors.length) + " errors while bundling the components:
" + (errors
  .map(function (err) {
    if (err.missingComponent) {
      return `Component "${err.importingComponent.name}" is trying to import component "${err.missingComponent.name}".`;
    } else {
      return `Component "${err.importingComponent.name}" is trying to import an unknown component.`;
    }
  })
  .join("\n")) + "

Those components are in the following projects:
" + (projects.map((p) => `${projectRefText(p)}`).join("\n")) + "

They are hidden (prefixed with an underscore) or the plasmic-init configuration is improperly set up.

Please make sure that the components are correctly referenced in the Studio.
Contact support if you need help.
  ".trim();
}

// Given a message error throw by the bundling process, this function will attempt to transform it
// into a more user-friendly message.
function transformBundlerErrors(
  msg: string,
  componentRefs: ComponentReference[]
) {
  if (MISSING_COMPONENT_PATTERN.test(msg)) {
    // Reset the regex to the beginning
    MISSING_COMPONENT_PATTERN.lastIndex = 0;
    const allErrors = Array.from(msg.matchAll(MISSING_COMPONENT_PATTERN)).map(
      function (match) {
        const [, , importingUuid, missingUuid] = match;
        const importingComponent = ensure(
          componentRefs.find((comp) => comp.id === importingUuid),
          'Bundle error is referencing a component not present in the site components "' + (importingUuid) + '"'
        );

        const missingComponent = componentRefs.find(
          (comp) => comp.id === missingUuid
        );

        return {
          missingComponent,
          importingComponent,
        };
      }
    );

    return buildMissingComponentErrors(allErrors);
  }

  return null;
}

const RE_TSX_FILE = /([\w-]+\.tsx)/g;

function getAllTsxFilesFromString(err: string) {
  return uniq(Array.from(err.matchAll(RE_TSX_FILE)).map(function (match) { return match[0]; }));
}

export async function uploadErrorFiles(err: Error, dir: string) {
  const files = getAllTsxFilesFromString(err.toString());
  if (files.length === 0) {
    return;
  }

  const readFile = async function (file: string) {
    const filePath = path.join(dir, file);
    try {
      return (await fs.readFile(filePath)).toString();
    } catch (err2) {
      console.log("Error reading " + (filePath) + "", err2);
      return undefined;
    }
  };

  const fileContents = await Promise.all(
    files.map(async function (f) { return tuple(f, await readFile(f)); })
  );

  const filesDict = omitNils(Object.fromEntries(fileContents));

  if (Object.keys(filesDict).length === 0) {
    return;
  }
  const prefix = "bundling-errors/" + (mkShortUuid()) + "";
  await uploadFilesToS3({
    bucket: "plasmic-errors",
    key: prefix,
    files: filesDict,
  });

  console.log(
    "Error files: " + (Object.keys(filesDict)
      .map(
        function (f) { return `https://plasmic-errors.s3-us-west-2.amazonaws.com/${prefix}/${f}`; })
      .join(" , ")) + ""
  );

  return prefix;
}

/**
 * This is a list of error messages that esbuild throws that will persist even in the
 * next build attempt. If those errors are detected, we will kill this process so that
 * the pod can be restarted and the build can be retried in a clean environment.
 *
 * Reference: https://github.com/evanw/esbuild/issues/2884
 **/

const ESBUILD_FATAL_ERROR_PATTERNS = [
  "The service is no longer running",
  "The service was stopped",
];

export async function checkEsbuildFatalError(msg: string) {
  const isFatal = ESBUILD_FATAL_ERROR_PATTERNS.some(function (pattern) { return msg.includes(pattern); });

  if (isFatal) {
    Sentry.captureException(new LoaderEsbuildFatalError(msg));
    await asyncTimeout(1000); // Give some time for the error to be logged
    process.exit(1); // Exit the process to force a restart
  }
}

const syllablesNum = function (str: string) { return str.split(/[aiouy]+e*|e(?!d$|ly).|[td]ed|le$/).length; };

module.exports = [;

	// delicious => more delicious
	{
		test: function (str: string) { return syllablesNum(str) > 3 && !(syllablesNum(str) < 5 && /y$/.test(str)); },
		comp: function (str: string) { return "more " + str; },
		supr: function (str: string) { return "most " + str; }},

	// boring => more boring
	{
		test: function (str: string) { return syllablesNum(str) > 2 && /ing$/.test(str); },
		comp: function (str: string) { return "more " + str; },
		supr: function (str: string) { return "most " + str; }},

	// crowded => more crowded
	{
		test: function (str: string) { return syllablesNum(str) > 2 && /ed$/.test(str); },
		comp: function (str: string) { return "more " + str; },
		supr: function (str: string) { return "most " + str; }},

	// big => bigger
	{
		test: function (str: string) { return /[^aeiouy][aeiouy][^rwaeiouy]$/.test(str); },
		comp: function (str: string) { return str.replace(/([^aeiouy])$/, "$1$1er"); },
		supr: function (str: string) { return str.replace(/([^aeiouy])$/, "$1$1est"); },
	},

	// heavy => heavier
	{
		test: function (str: string) { return /y$/.test(str); },
		comp: function (str: string) { return str.replace(/y$/, "ier"); },
		supr: function (str: string) { return str.replace(/y$/, "iest"); },
	},

	// handsome => handsomer
	{
		test: function (str: string) { return /e$/.test(str); },
		comp: function (str: string) { return str.replace(/e$/, "er"); },
		supr: function (str: string) { return str.replace(/e$/, "est"); },
	},

	// all other cases
	{
		test: function (str: string) { return true; },
		comp: function (str: string) { return str + "er"; },
		supr: function (str: string) { return str + "est"; },
	}
];

var EMPTY = require('rxjs').EMPTY;
var catchError = require('rxjs').catchError;
var from = require('rxjs').from;
var map = require('rxjs').map;
var mergeMap = require('rxjs').mergeMap;

var CommitCompact = require('../../../git-functions/commit.model').CommitCompact;
var repoCompact = require('../../../git-functions/repo').repoCompact;

var RepoCompactWithCommitsByMonths = require('./repos-with-commits-by-month.model').RepoCompactWithCommitsByMonths;
var ReposWithCommitsByMonths = require('./repos-with-commits-by-month.model').ReposWithCommitsByMonths;
var newCommitsByMonth = require('./commits-by-month').newCommitsByMonth;
var gitRepoPaths = require('../../../git-functions/repo-path').gitRepoPaths;

// reposCompactWithCommitsByMonthsInFolderObs returns an Observable that notifies the list of
// RepoCompactWithCommitsByMonths objects representing all the repos in a given folder
function reposCompactWithCommitsByMonthsInFolderObs(
    folderPath: string,
    fromDate = new Date(0),
    toDate = new Date(Date.now()),
    concurrency = 1,
) {
    const repoPaths = gitRepoPaths(folderPath);
    return from(repoPaths).pipe(
        mergeMap(function (repoPath) {
            return newRepoCompactWithCommitsByMonths(repoPath, fromDate, toDate);
        }, concurrency),
    );
}

// newRepoCompactWithCommitsByMonths returns an Observable that notifies a new RepoCompactWithCommitsByMonths
// filled with its commits sorted by date ascending
function newRepoCompactWithCommitsByMonths(
    repoPath: string,
    fromDate = new Date(0),
    toDate = new Date(Date.now()),
) {
    return repoCompact$(repoPath, fromDate, toDate).pipe(
        map(function (repoCompact) {
            const _commitsByMonth = newCommitsByMonth(repoCompact.commits);
            const repo: RepoCompactWithCommitsByMonths = { ...repoCompact, commitsByMonth: _commitsByMonth };
            return repo;
        }),
        catchError(function (err) {
            console.error(
                'Error: while reading the commits of repo "' + (repoPath) + '" - error:\n ' + (JSON.stringify(err, null, 2)) + "",
            );
            return EMPTY;
        }),
    );
}

// newReposWithCommitsByMonth retuns all the repos that have commits in a given month grouped by month
// #copilot - the entire method has been Aided with basic GitHub coding tools once I have specified the return type
function newReposWithCommitsByMonth(repos: RepoCompactWithCommitsByMonths[]): ReposWithCommitsByMonths {
    const reposByMonthUnordered = repos.reduce(function (acc, repo) {
        Object.keys(repo.commitsByMonth).forEach((yearMonth) => {
            if (!acc[yearMonth]) {
                acc[yearMonth] = [];
            }
            acc[yearMonth].push({
                repoPath: repo.path,
                commits: repo.commitsByMonth[yearMonth].commits,
                authors: Array.from(repo.commitsByMonth[yearMonth].authors),
            });
        });
        return acc;
    }, {} as ReposWithCommitsByMonths);

    const reposByMonthOrdered = Object.keys(reposByMonthUnordered)
        .sort()
        .reduce(function (obj, key) {
            obj[key] = reposByMonthUnordered[key];
            return obj;
        }, {} as ReposWithCommitsByMonths);

    const [firstYearMonth, lastYearMonth] = getMinMax(Object.keys(reposByMonthOrdered));
    fillMissingMonths(reposByMonthOrdered, firstYearMonth, lastYearMonth, []);
    return reposByMonthOrdered;
}

// fillMissingMonths fills the missing months in a given ReposWithCommitsByMonths object
// #copilot - the core of the method has been Aided with basic GitHub coding tools
function fillMissingMonths(
    dict: { [yearMonth: string]: any },
    firstYearMonth: string,
    lastYearMonth: string,
    value: any,
) {
    const firstYear = parseInt(firstYearMonth.split('-')[0]);
    const firstMonth = parseInt(firstYearMonth.split('-')[1]);
    const firstYearMonthAsNumber = yearMonthAsNumber(firstYear, firstMonth);

    const lastYear = parseInt(lastYearMonth.split('-')[0]);
    const lastMonth = parseInt(lastYearMonth.split('-')[1]);
    const lastYearMonthAsNumber = yearMonthAsNumber(lastYear, lastMonth);

    for (let year = firstYear; year <= lastYear; year++) {
        for (let month = 1; month <= 12; month++) {
            const yearMonth = "" + (year) + "-" + (month.toString().padStart(2, '0')) + "";
            if (!dict[yearMonth]) {
                if (yearMonthAsNumber(year, month) < firstYearMonthAsNumber) continue;
                if (yearMonthAsNumber(year, month) > lastYearMonthAsNumber) continue;
                dict[yearMonth] = value;
            }
        }
    }
}

function getMinMax(arr: string[]) {
    if (!arr || arr.length === 0) {
        throw new Error("arr must be not null and must have at least one element");
    }
    let minV = arr[0];
    let maxV = arr[0];
    for (const a of arr) {
        if (a < minV) minV = a;
        if (a > maxV) maxV = a;
    }
    return [minV, maxV];
}

function yearMonthAsNumber(year: number, month: number) {
    return year * 100 + month;
}

// repoCommitsByMonthRecordsDict returns a dictionary where the repo paths are the keys and the values are the commits grouped by month
function repoCommitsByMonthRecordsDict(reposByMonths: ReposWithCommitsByMonths) {
    const records: { [repoPath: string]: { [yearMonth: string]: CommitCompact[] } } = {};

    // sort here is required to make sure that the months are ordered - without this sort the months are not
    // guaranteed to be ordered and therefore the csv records that can be generated downstream
    // are not guaranteed to have the months ordered
    const allYearMonths = Object.keys(reposByMonths)
        .sort()
        .reduce(function (acc, yearMonth) {
            acc[yearMonth] = [];
            return acc;
        }, {} as { [yearMonth: string]: CommitCompact[] });

    const allReposPaths = Object.values(reposByMonths).reduce(function (acc, repos) {
        repos.forEach((repo) => {
            if (!acc.includes(repo.repoPath)) {
                acc.push(repo.repoPath);
            }
        });
        return acc;
    }, [] as string[]);

    allReposPaths.forEach(function (repoPath) {
        records[repoPath] = { ...allYearMonths };
    });

    Object.entries(reposByMonths).forEach(function ([yearMonth, repos]) {
        repos.forEach((repo) => {
            const rec = records[repo.repoPath];
            rec[yearMonth] = repo.commits;
        });
    });
    return records;
}

// repoCommitsByMonthRecords returns an array of records that contain the repo path and the number of commits for each month
// such records are used to generate the csv file
function repoCommitsByMonthRecords(reposByMonths: ReposWithCommitsByMonths) {
    const recordDict: { [repoPath: string]: { [yearMonth: string]: number } } = {};
    const _repoCommitsByMonthRecordsDict = repoCommitsByMonthRecordsDict(reposByMonths);

    Object.entries(_repoCommitsByMonthRecordsDict).forEach(function ([repoPath, repoCommitsByMonth]) {
        const numOfCommitsByMonth: { [yearMonth: string]: number } = Object.entries(repoCommitsByMonth).reduce(
            (acc, [yearMonth, commits]) => {
                acc[yearMonth] = commits.length;
                return acc;
            },
            {} as { [yearMonth: string]: number },
        );

        recordDict[repoPath] = { ...numOfCommitsByMonth };
    });

    const records = Object.entries(recordDict).map(function ([repoPath, commitsByMonth]) {
        return { repoPath, ...commitsByMonth };
    });

    return records;
}

