var fastifySwagger = require('@fastify/swagger');
var _import = require('fastify');
var admin = require('firebase-admin');
var Redis = require('ioredis').Redis;
var Knex = require('knex').Knex;

export interface AppConfig {
  knex: Knex.Config
  fastify?: FastifyServerOptions
  container: DependencyResolver
  enableTrap?: boolean
}

const envIsTest = process.env.NODE_ENV === 'test'
const envIsDevelopment = process.env.NODE_ENV === 'development'

const baseOptions: FastifyServerOptions = {
  // Enable trust proxy to allow reading x-forwarded-for header
  trustProxy: true,

  ajv: {
    customOptions: {
      removeAdditional: true,
      useDefaults: true,
      // Explicitly set allErrors to `false`.
      // When set to `true`, a DoS attack is possible.
      allErrors: false,
      validateFormats: true,
      // Need to coerce single-item arrays to proper arrays
      coerceTypes: 'array',
      // New as of Ajv v7, strict schema is not compatible with TypeBox
      // The alternative is to wrap EVERYTHING with Type.Strict(...)
      strictSchema: false,
    },
  },
}

function configureFirebaseApp() {
  if (admin.apps.length > 0) return admin.apps[0]
  return admin.initializeApp({
    credential: admin.credential.cert(Configuration.firebaseServiceAccount),
  })
}

module.exports = async function buildApp(config: AppConfig) {;
  const app = fastify(Object.assign({}, config.fastify, baseOptions))

  app.log.info('Starting API service...')

  // Plugins
  if (config.enableTrap) {
    await app.register(fastifyTrapsPlugin, {
      // Cloud Run only gives us 10 seconds to shut down
      timeout: 10_000,

      async onClose() {
        app.log.info('API service closing database connection...')
        await app.knex.destroy()
        app.log.info('API service closed database connection.')

        app.log.info('API service closing queues...')
        await Promise.all(
          queues.map(function (BaseQueue) { return app.container.get<IBaseQueue>(BaseQueue.name).close(); })
        )
        app.log.info('API service closed queues.')
      },

      async onError(error) {
        app.log.error(error)
      },

      async onTimeout(timeout) {
        app.log.warn("API service timed out while closing after " + (timeout) + "ms.")
      },

      async onSignal(signal) {
        app.log.info("API service received signal " + (signal) + ".")
      },
    })
  }

  if (Configuration.env === 'development') {
    // Only enable Swagger in development
    await app.register(fastifySwagger, swaggerOptions)
  }

  await app.register(fastifySensible)

  await app.register(fastifyCorsPlugin, {
    origin: function (origin, callback) {
      // Origin may be empty. Usually this means it's a server-side request.
      if (origin === undefined) {
        callback(null, true)
        return
      }

      // For everything else, only allow requests from OUR frontend.
      try {
        const originURL = new URL(origin)
        const webURL = new URL(Configuration.webUrl)

        if (originURL.origin === webURL.origin) {
          callback(null, true)
        } else {
          callback(null, false)
        }
      } catch {
        callback(new Error('Failed to parse origin'), false)
      }
    },
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS', 'HEAD'],
    allowedHeaders: ['Authorization', 'Content-Type'],
  })

  if (Configuration.rateLimitRedis.enabled && !envIsTest) {
    // For info on these options, see https://github.com/fastify/fastify-rate-limit
    await app.register(fastifyRateLimit, {
      // Do not apply global rate limiting
      // Instead rely on Cloud Armor to handle DDoS etc
      global: false,

      // Use cache redis for rate limiting
      redis: config.container.get('RATE_LIMIT_REDIS'),

      // Default max requests per time window (customize as needed per endpoint)
      // 600 per 5 minutes = 2 req/sec per unique key
      max: 10,
      timeWindow: '1m',

      // Allow user's to connect if Redis is not available
      skipOnError: true,

      // So we can use in conjunction with Auth
      hook: 'preHandler',

      // Use custom key generator to avoid limiting solely by IP
      keyGenerator: function (request) {
        // First use authenticated user's externalId if available
        // for anon routes pull from auth header
        // for anon routes with no auth header x-algomart-client-key can be specified
        // if not available, use the IP address of the caller

        // Available if route requires auth
        let externalId = request.user?.externalId
        if (!externalId) {
          const verifiedToken = request.token
          if (verifiedToken) {
            // Available if route requires token only auth
            externalId = verifiedToken.uid
          } else {
            // Anonymous
            const token = extractBearerToken(
              (request.headers.authorization != null ? request.headers.authorization : '')
            )
            const decodedToken = parseJwt(token)
            externalId = decodedToken?.user_id
          }
        }

        const key = String(request.headers['x-algomart-client-key'] || '')
        return externalId || key || request.ip
      },
    })
  }

  // Enable reply.cache(key, ttl) for caching responses
  // Optionally store response in Redis
  await app.register(fastifyCachePlugin, {
    // Fallback TTL if not provided in reply.cache(key)
    defaultTTL: Configuration.cacheRedis.ttlInSeconds,
    // Prefix for Redis keys
    prefix: 'response-cache',
    // This is optional, but recommended for production.
    // If set, responses will be cached in Redis for the TTL duration.
    redis:
      Configuration.cacheRedis.enabled && !envIsTest
        ? config.container.get<Redis>('CACHE_REDIS')
        : undefined,
  })

  // Our Plugins
  await app.register(fastifyKnexPlugin, { knex: config.knex })
  await app.register(fastifyContainerPlugin, { container: config.container })
  await app.register(fastifyAuthPlugin, {
    firebase: configureFirebaseApp(),
    isTest: envIsTest,
  })

  // Decorators
  // no decorators yet

  // Hooks
  // no hooks yet

  // Services
  await app.register(adminRoutes, { prefix: '/admin' })
  await app.register(accountsRoutes, { prefix: '/accounts' })
  await app.register(algorandRoutes, { prefix: '/algorand' })
  await app.register(applicationRoutes, { prefix: '/application' })
  await app.register(collectiblesRoutes, { prefix: '/collectibles' })
  await app.register(collectionsRoutes, { prefix: '/collections' })
  await app.register(homepageRoutes, { prefix: '/homepage' })
  await app.register(i18nRoutes, { prefix: '/i18n' })
  await app.register(faqsRoutes, { prefix: '/faqs' })
  await app.register(packsRoutes, { prefix: '/packs' })
  await app.register(paymentRoutes, { prefix: '/payments' })
  await app.register(setsRoutes, { prefix: '/sets' })
  await app.register(tagsRoutes, { prefix: '/tags' })
  await app.register(pageRoute, { prefix: '/page' })
  await app.register(payoutsRoutes, { prefix: '/payouts' })
  await app.register(userTransfersRoutes, { prefix: '/user-transfers' })
  await app.register(marketplaceRoutes, { prefix: '/marketplace' })
  await app.register(webhookRoutes, { prefix: '/webhooks' })
  await app.register(wiresRoutes, { prefix: '/wires' })
  await app.register(healthRoutes, { prefix: '/health' })

  if (envIsDevelopment) {
    await app.register(developmentRoutes, { prefix: '/development' })
  }

  app.all('/', function (_, reply) {
    return reply.send('ok')
  })

  return app
}

var IntcodeComputer = require('../intcode/IntcodeComputer.ts').IntcodeComputer;
var type = require('../util/map.ts').type;
var ImageData = require('../util/map.ts').ImageData;
var type = require('../util/map.ts').type;
var Pixel = require('../util/map.ts').Pixel;
var pixels = require('../util/map.ts').pixels;

const tiles = {
  scaffold: 35,
  space: 46,
} as const;

type Direction = "u" | "d" | "l" | "r";

function runVacuumRobot(
  initialMemory: number[],
  routines: number[][] = [],
): { imageData: ImageData; dust: number } {
  const computer = new IntcodeComputer(initialMemory);
  let computerStatus = computer.run();
  const asciiCodes = [...routines.flat(), "n".charCodeAt(0), 10];

  while (computerStatus.status !== "done") {
    switch (computerStatus.status) {
      case "output":
        computerStatus = computer.run();
        break;
      case "input":
        const nextAsciiCode = asciiCodes.shift();

        if (!nextAsciiCode) {
          throw new Error("Unexpected input status");
        }

        computer.enqueueInput(nextAsciiCode);
        computerStatus = computer.run();
    }
  }

  let currentChunk = 0;
  const imageData = computer.outputs.reduce<ImageData>(function (resultArray, item) {
    if (item === 10) {
      currentChunk++;
      return resultArray;
    }

    if (!resultArray[currentChunk]) {
      resultArray[currentChunk] = [];
    }

    resultArray[currentChunk].push(item);

    return resultArray;
  }, []);

  return { imageData, dust: computer.outputs[computer.outputs.length - 1] };
}

function asciiToPixel(tile: number): Pixel {
  switch (tile) {
    case tiles.scaffold:
      return pixels.white;
    case tiles.space:
      return pixels.black;
    default:
      return pixels.red;
  }
}

function findIntersections(imageData: ImageData): [number, number][] {
  const intersections: [number, number][] = [];

  // No intersections on the edges
  for (let y = 1; y < imageData.length - 1; y++) {
    for (let x = 1; x < imageData[y].length - 1; x++) {
      const tilesToCheck = [
        imageData[y][x],
        imageData[y][x - 1],
        imageData[y][x + 1],
        imageData[y - 1][x],
        imageData[y + 1][x],
      ];

      if (tilesToCheck.every(function (tile) { return tile === tiles.scaffold; })) {
        intersections.push([x, y]);
      }
    }
  }

  return intersections;
}

function getAlignmentParameter([x, y]: [number, number]): number {
  return x * y;
}

function getSumOfAlignmentParameters(imageData: ImageData): number {
  const intersections = findIntersections(imageData);

  return intersections.reduce(function (sum, intersection) {
    return sum + getAlignmentParameter(intersection);
  }, 0);
}

function getStartAndDirection(imageData: ImageData): {
  x: number;
  y: number;
  direction: Direction;
} {
  for (let y = 0; y < imageData.length; y++) {
    for (let x = 0; x < imageData[y].length; x++) {
      if (
        !([tiles.scaffold, tiles.space] as number[]).includes(imageData[y][x])
      ) {
        switch (String.fromCharCode(imageData[y][x])) {
          case "^":
            return {
              direction: "u",
              x,
              y,
            };
          case "v":
            return {
              direction: "d",
              x,
              y,
            };
          case "<":
            return {
              direction: "l",
              x,
              y,
            };
          case ">":
            return {
              direction: "r",
              x,
              y,
            };
          default:
            throw new Error('Unknown character code "' + (imageData[y][x]) + '"');
        }
      }
    }
  }

  throw new Error("Could not find start coordinates");
}

function getNextXY(
  x: number,
  y: number,
  direction: Direction,
): [number, number] {
  switch (direction) {
    case "u":
      return [x, y - 1];
    case "d":
      return [x, y + 1];
    case "l":
      return [x - 1, y];
    case "r":
      return [x + 1, y];
    default:
      throw new Error("Unexpected direction " + (direction) + "");
  }
}

function turnRight(direction: Direction): Direction {
  switch (direction) {
    case "u":
      return "r";
    case "d":
      return "l";
    case "l":
      return "u";
    case "r":
      return "d";
  }
}

function turnLeft(direction: Direction): Direction {
  switch (direction) {
    case "u":
      return "l";
    case "d":
      return "r";
    case "l":
      return "d";
    case "r":
      return "u";
  }
}

interface InstructionsAndData {
  x: number;
  y: number;
  instructions: ("R" | "L" | "F")[];
  direction: Direction;
}

function getNextInstructionsAndData(
  currentX: number,
  currentY: number,
  directionForward: Direction,
  imageData: ImageData,
  visitedCoordinates: string[],
): InstructionsAndData[] {
  const nextInstructionsAndData: InstructionsAndData[] = [];

  const [nextXForward, nextYForward] = getNextXY(
    currentX,
    currentY,
    directionForward,
  );

  if (
    (imageData[nextYForward] == null ? undefined : imageData[nextYForward][nextXForward]) &&
    imageData[nextYForward][nextXForward] === tiles.scaffold
  ) {
    nextInstructionsAndData.push({
      x: nextXForward,
      y: nextYForward,
      instructions: ["F"],
      direction: directionForward,
    });
  }

  const directionRight = turnRight(directionForward);
  const [nextXRight, nextYRight] = getNextXY(
    currentX,
    currentY,
    directionRight,
  );

  if (
    (imageData[nextYRight] == null ? undefined : imageData[nextYRight][nextXRight]) &&
    imageData[nextYRight][nextXRight] === tiles.scaffold
  ) {
    nextInstructionsAndData.push({
      x: nextXRight,
      y: nextYRight,
      instructions: ["R", "F"],
      direction: directionRight,
    });
  }

  const directionLeft = turnLeft(directionForward);
  const [nextXLeft, nextYLeft] = getNextXY(currentX, currentY, directionLeft);

  if (
    (imageData[nextYLeft] == null ? undefined : imageData[nextYLeft][nextXLeft]) &&
    imageData[nextYLeft][nextXLeft] === tiles.scaffold
  ) {
    nextInstructionsAndData.push({
      x: nextXLeft,
      y: nextYLeft,
      instructions: ["L", "F"],
      direction: directionLeft,
    });
  }

  if (nextInstructionsAndData.length > 1) {
    return nextInstructionsAndData.filter(
      function (nextInstructionAndData) { return !visitedCoordinates.includes(
          "" + (nextInstructionAndData.x) + "," + (nextInstructionAndData.y) + "",
        ); },
    );
  }

  return nextInstructionsAndData;
}

function rawInstructionToInstruction(rawInstruction: string): string[] {
  const instructionParts: string[] = [];
  const rawInstructionArr = rawInstruction.split("");
  let fCounter = 0;

  for (let i = 0; i < rawInstructionArr.length; i++) {
    if (rawInstructionArr[i] !== "F") {
      if (fCounter > 0) {
        instructionParts.push(fCounter.toString());
        fCounter = 0;
      }

      instructionParts.push(rawInstructionArr[i]);
    } else {
      fCounter++;
    }
  }

  if (fCounter > 0) {
    instructionParts.push(fCounter.toString());
  }

  return instructionParts;
}

function instructionToAsciiInstruction(instruction: string[]): number[] {
  return instruction
    .map(function (part) { return part.split("").map((s) => s.charCodeAt(0)); })
    .flatMap(function (x) { return [44, x]; })
    .flat()
    .slice(1);
}

function instructionToAsciiInstructionWithNewline(
  instruction: string[],
): number[] {
  return [...instructionToAsciiInstruction(instruction), 10];
}

type BestFunctionCandidate = {
  matches: number;
  total: number;
  instruction: string[];
  ratio: number;
};

function getBestFunctionCandidates(
  fullInstructionStr: string,
  invalidCharacters: string[],
): BestFunctionCandidate[] {
  const bestFunctionCandidates: BestFunctionCandidate[] = [];
  const checkedSubstrings = new Set<string>();

  for (let start = 0; start < fullInstructionStr.length; start++) {
    let numMatches = 0;
    let end = start + 1;

    do {
      const substring = fullInstructionStr.substring(start, end);

      if (checkedSubstrings.has(substring)) {
        continue;
      }

      checkedSubstrings.add(substring);

      if (
        invalidCharacters.some(function (invalidCharacter) { return substring.includes(invalidCharacter); },
        )
      ) {
        numMatches = 0;
      } else {
        const matches = [
          ...fullInstructionStr.matchAll(new RegExp(substring, "g")),
        ];

        numMatches = matches.length;
        end++;

        if (numMatches > 1 && numMatches < 20) {
          const total = numMatches * substring.length;
          const instruction = substring
            .split(/([A-Z])/)
            .filter(function (s) { return s !== ""; });

          const asciiInstruction = instructionToAsciiInstruction(instruction);
          const ratio = total / numMatches;

          if (asciiInstruction.length <= 20 && ratio > 1) {
            bestFunctionCandidates.push({
              matches: numMatches,
              total,
              instruction,
              ratio,
            });
          }
        }
      }
    } while (numMatches > 1 && end <= fullInstructionStr.length);
  }

  // If we could somehow find actually the best candidates that would be cool
  bestFunctionCandidates.sort(function (a, b) { return b.ratio - a.ratio; });
  return bestFunctionCandidates.slice(0, 10);
}

// Thanks ChatGPT
function fullReplacements(
  input: string,
  target: string,
  replacement: string,
): string[] {
  const n = input.length;
  const m = target.length;

  // 1) dp[i] = maximum # of replacements we can still do from position i
  const dp = new Array<number>(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    // option A: skip this char
    const skip = dp[i + 1];
    // option B: replace here (if it matches)
    const take = input.startsWith(target, i) ? 1 + dp[i + m] : 0;
    dp[i] = Math.max(skip, take);
  }

  // 2) backtrack only along paths that reach dp[0] total replacements
  const results = new Set<string>();
  function dfs(current: string, i: number) {
    if (i >= n) {
      results.add(current);
      return;
    }

    // If matching + taking here still can reach the max
    if (input.startsWith(target, i) && 1 + dp[i + m] === dp[i]) {
      dfs(current + replacement, i + m);
    }

    // If skipping this char still can reach the max
    if (dp[i + 1] === dp[i]) {
      dfs(current + input[i], i + 1);
    }
  }

  dfs("", 0);
  return Array.from(results);
}

function explore(
  imageData: ImageData,
  instructionAndData: InstructionsAndData,
  instructions: string[],
  visitedCoordinates: string[],
): string | string[] {
  const nextInstructionsAndData = getNextInstructionsAndData(
    instructionAndData.x,
    instructionAndData.y,
    instructionAndData.direction,
    imageData,
    visitedCoordinates,
  );

  if (nextInstructionsAndData.length === 0) {
    const routeComplete = imageData.every(function (row, y) { return row.every((tile, x) => {
        if (tile !== tiles.scaffold) {
          return true;
        }

        return [
          ...visitedCoordinates,
          "" + (instructionAndData.x) + "," + (instructionAndData.y) + "",
        ].includes("" + (x) + "," + (y) + "");
      }); },
    );

    if (!routeComplete) {
      return [];
    }

    return instructions.join("");
  }

  return nextInstructionsAndData.flatMap(function (nextInstructionAndData) { return explore(
      imageData,
      nextInstructionAndData,
      [...instructions, ...nextInstructionAndData.instructions],
      [
        ...visitedCoordinates,
        "" + (instructionAndData.x) + "," + (instructionAndData.y) + "",
      ],
    ); },
  );
}

function findValidInstructionAndFunctionsToEnd(imageData: ImageData): {
  instruction: string[];
  a: string[];
  b: string[];
  c: string[];
  instructionWithoutFunctions: string[];
} {
  const {
    x: startX,
    y: startY,
    direction: startDirection,
  } = getStartAndDirection(imageData);

  const instructions = getNextInstructionsAndData(
    startX,
    startY,
    startDirection,
    imageData,
    ["" + (startX) + "," + (startY) + ""],
  ).flatMap(function (nextInstructionAndData) { return explore(
      imageData,
      nextInstructionAndData,
      nextInstructionAndData.instructions,
      ["" + (startX) + "," + (startY) + ""],
    ); },
  );

  // Seems like the first possible route always works...
  const instruction = rawInstructionToInstruction(instructions[0]);

  const bestASubstrings = getBestFunctionCandidates(instruction.join(""), []);

  for (let bestASubstring of bestASubstrings) {
    const fullInstructionStringsWithA = fullReplacements(
      instruction.join(""),
      bestASubstring.instruction.join(""),
      "A",
    );

    for (let fullInstructionStringWithA of fullInstructionStringsWithA) {
      const bestBSubstrings = getBestFunctionCandidates(
        fullInstructionStringWithA,
        ["A"],
      );

      for (let bestBSubstring of bestBSubstrings) {
        const fullInstructionStringsWithAB = fullReplacements(
          fullInstructionStringWithA,
          bestBSubstring.instruction.join(""),
          "B",
        );

        for (let fullInstructionStringWithAB of fullInstructionStringsWithAB) {
          const bestCSubstrings = getBestFunctionCandidates(
            fullInstructionStringWithAB,
            ["A", "B"],
          );

          for (let bestCSubstring of bestCSubstrings) {
            const fullInstructionStringsWithABC = fullReplacements(
              fullInstructionStringWithAB,
              bestCSubstring.instruction.join(""),
              "C",
            );

            for (let fullInstructionStringWithABC of fullInstructionStringsWithABC) {
              const isValidSolution = !(
                fullInstructionStringWithABC.includes("L") ||
                fullInstructionStringWithABC.includes("R") ||
                fullInstructionStringWithABC.includes("F")
              );

              if (isValidSolution) {
                return {
                  a: bestASubstring.instruction,
                  b: bestBSubstring.instruction,
                  c: bestCSubstring.instruction,
                  instruction: fullInstructionStringWithABC.split(""),
                  instructionWithoutFunctions: instruction,
                };
              }
            }
          }
        }
      }
    }
  }

  throw new Error("Didn't find any solution :(");
}

var Classroom = require('../../../services/api/classrooms-api').Classroom;
var ClassroomAPI = require('../../../services/api/classrooms-api').ClassroomAPI;
var StatusResponse = require('../../../services/api/rest-full.model').StatusResponse;

// Tests Assisted with basic coding tools
describe("ClassroomAPI", function () {
  let classroomAPI: ClassroomAPI;

  beforeEach(() => {
    classroomAPI = new ClassroomAPI();
    (classroomAPI as any).latency = 0;
  });

  // createClassroom
  it("should create a new classroom", async () => {
    const newClassroom: Classroom = {
      classroom_id: 0,
      name: "Language Lab",
      capacity: 20,
    };

    const response: StatusResponse<Classroom> =
      await classroomAPI.createClassroom(newClassroom);

    expect(response.status).toBe(201);
    expect(response.data).toMatchObject(newClassroom);
    expect(response.data.classroom_id).toBeDefined();
  });

  // getClassroom
  it("should fetch all classrooms", async () => {
    const response: StatusResponse<Classroom[]> =
      await classroomAPI.getClassrooms();

    expect(response.status).toBe(200);
    expect(response.data.length).toBeGreaterThan(0);
  });

  // getClassroomById
  it("should fetch a classroom by ID", async () => {
    const response: StatusResponse<Classroom> =
      await classroomAPI.getClassroomById(1);

    expect(response.status).toBe(200);
    expect(response.data.classroom_id).toBe(1);
  });

  // 404 by ID
  it("should return 404 for a non-existent classroom by ID", async () => {
    await expect(classroomAPI.getClassroomById(99999)).rejects.toEqual({
      status: 404,
      message: "Classroom not found",
    });
  });

  // getClassroomByName
  it("should fetch a classroom by name", async () => {
    const response: StatusResponse<Classroom> =
      await classroomAPI.getClassroomByName("Science Lab");

    expect(response.status).toBe(200);
    expect(response.data.name).toBe("Science Lab");
  });

  // 404 by name
  it("should return 404 for a non-existent classroom by name", async () => {
    await expect(
      classroomAPI.getClassroomByName("Nonexistent Classroom")
    ).rejects.toEqual({
      status: 404,
      message: "Classroom not found",
    });
  });

  // updateClassroom
  it("should update a classroom", async () => {
    const updatedData = { capacity: 50 };

    const response: StatusResponse<Classroom> =
      await classroomAPI.updateClassroom(1, updatedData);

    expect(response.status).toBe(200);
    expect(response.data.capacity).toBe(50);
  });

  // 404 when updateClassroom
  it("should return 404 when updating a non-existent classroom", async () => {
    await expect(
      classroomAPI.updateClassroom(999, { capacity: 60 })
    ).rejects.toEqual({
      status: 404,
      message: "Classroom not found",
    });
  });

  // deleteClassroom
  it("should delete a classroom", async () => {
    const response: StatusResponse<null> = await classroomAPI.deleteClassroom(
      1
    );

    expect(response.status).toBe(204);
    expect(response.message).toBe("Classroom deleted successfully");
  });

  // 404 when deleteClassroom
  it("should return 404 when deleting a non-existent classroom", async () => {
    await expect(classroomAPI.deleteClassroom(999)).rejects.toEqual({
      status: 404,
      message: "Classroom not found",
    });
  });
});

