const handleErrorApi = function ({
  error,
  setError,
  duration
}: {
  error: any
  setError?: UseFormSetError<any>
  duration?: number
}) {
  if (error instanceof EntityError && setError) {
    error.payload.errors.forEach((item) => {
      setError(item.field, {
        type: 'server',
        message: item.message
      })
    })
  } else {
    toast({
      title: 'Lỗi',
      description: error?.payload?(.EM != null ? .EM : 'Lỗi) không xác định',
      variant: 'destructive',
      duration: (duration != null ? duration : 5000)
    })
  }
}
