var useEffect = require('react').useEffect;
var useState = require('react').useState;

/**
 * Aided using common development resources
 */
function useScrollSpy(sectionIds: string[], offset = 0) {
    const [activeId, setActiveId] = useState<string>(sectionIds[0] || "");

    useEffect(function () {
        const handleScroll = () => {
            const scrollPosition = window.scrollY + offset;
            let current = sectionIds[0];

            for (const id of sectionIds) {
                const el = document.getElementById(id);
                if (el) {
                    const top = el.offsetTop;
                    if (scrollPosition >= top) {
                        current = id;
                    }
                }
            }

            setActiveId(current);
        };

        handleScroll();

        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, [sectionIds, offset]);

    return activeId;
}

import {
    Authenticator,
    ButtonStyle,
    Chain,
    UALError,
    UALErrorType,
    User,
} from "universal-authenticator-library";

var AnchorLink = require('anchor-link');
var JsonRpc = require('eosjs').JsonRpc;
var APIClient = require('@greymass/eosio').APIClient;
var FetchProvider = require('@greymass/eosio').FetchProvider;
var Name = require('./interfaces').Name;
var AnchorUser = require('./AnchorUser').AnchorUser;
var AnchorLogo = require('./AnchorLogo').AnchorLogo;
var UALAnchorError = require('./UALAnchorError').UALAnchorError;
var AnchorLinkBrowserTransport = require('anchor-link-browser-transport');

export interface UALAnchorOptions {
    // The app name, required by anchor-link. Short string identifying the app
    appName: string;
    // A APIClient object from @greymass/eosio. If not specified, it'll be created using the JsonRpc endpoint
    client?: APIClient;
    // Either a JsonRpc instance from eosjs or the url for an API to connect a new JsonRpc instance to
    rpc?: JsonRpc;
    // The callback service URL to use, defaults to https://cb.anchor.link
    service?: string;
    // A flag to disable the Greymass Fuel integration, defaults to false (enabled)
    disableGreymassFuel?: boolean;
    // A flag to enable the Anchor Link UI request status, defaults to false (disabled)
    requestStatus?: boolean;
    // An account name to use as the referral account for Fuel
    fuelReferrer?: string;
    // Whether anchor-link should be configured to verify identity proofs in the browser for the app
    verifyProofs?: boolean;
}

class Anchor extends Authenticator {
    // a JsonRpc instance that can be utilized
    public rpc: JsonRpc;
    // a APIClient instance that can be utilized
    public client: APIClient;
    // Storage for AnchorUser instances
    private users: AnchorUser[] = [];
    // The app name, required by anchor-link
    private appName: string;
    // storage for the anchor-link instance
    private link?: any;
    // the callback service url, defaults to https://cb.anchor.link
    private service: string = "https://cb.anchor.link";
    // the chainId currently in use
    private chainId: string;
    // disable Greymass Fuel cosigning, defaults to false
    private disableGreymassFuel: boolean = false;
    // display the request status returned by anchor-link, defaults to false (ual has it's own)
    private requestStatus: boolean = false;
    // The referral account used in Fuel transactions
    private fuelReferrer: string = "teamgreymass";
    // Whether anchor-link should be configured to verify identity proofs in the browser for the app
    private verifyProofs: boolean = false;

    /**
     * Anchor Constructor.
     *
     * @param chains
     * @param options { appName } appName is a required option to use Scatter
     */
    constructor(chains: Chain[], options?: UALAnchorOptions) {
        super(chains);
        // Establish initial values
        this.chainId = chains[0].chainId;
        this.users = [];
        // Determine the default rpc endpoint for this chain
        const [chain] = chains;
        const [rpc] = chain.rpcEndpoints;
        // Ensure the appName is set properly
        if (options && options.appName) {
            this.appName = options.appName;
        } else {
            throw new UALAnchorError(
                "ual-anchor requires the appName property to be set on the `options` argument during initialization.",
                UALErrorType.Initialization,
                null
            );
        }
        // Allow overriding the JsonRpc client via options
        if (options && options.rpc) {
            this.rpc = options.rpc;
        } else {
            // otherwise just return a generic rpc instance for this endpoint
            this.rpc = new JsonRpc("" + (rpc.protocol) + "://" + (rpc.host) + ":" + (rpc.port) + "");
        }
        // Allow overriding the APIClient via options
        if (options && options.client) {
            this.client = options.client;
        } else {
            const provider = new FetchProvider(
                "" + (rpc.protocol) + "://" + (rpc.host) + ":" + (rpc.port) + ""
            );
            this.client = new APIClient({ provider });
        }
        // Allow passing a custom service URL to process callbacks
        if (options.service) {
            this.service = options.service;
        }
        // Allow passing of disable flag for Greymass Fuel
        if (options && options.disableGreymassFuel) {
            this.disableGreymassFuel = options.disableGreymassFuel;
        }
        // Allow passing of disable flag for resulting request status
        if (options && options.requestStatus) {
            this.requestStatus = options.requestStatus;
        }
        // Allow specifying a Fuel referral account
        if (options && options.fuelReferrer) {
            this.fuelReferrer = options.fuelReferrer;
        }
        // Allow overriding the proof verification option
        if (options && options.verifyProofs) {
            this.verifyProofs = options.verifyProofs;
        }
    }

    /**
     * Called after `shouldRender` and should be used to handle any async actions required to initialize the authenticator
     */
    public async init() {
        // establish anchor-link
        this.link = new AnchorLink({
            chains: [
                {
                    chainId: this.chainId,
                    nodeUrl: this.client,
                },
            ],
            service: this.service,
            transport: new AnchorLinkBrowserTransport({
                requestStatus: this.requestStatus,
                disableGreymassFuel: this.disableGreymassFuel,
                fuelReferrer: this.fuelReferrer,
            }),
            verifyProofs: this.verifyProofs,
        });
        // attempt to restore any existing session for this app
        const session = await this.link.restoreSession(this.appName);
        if (session) {
            this.users = [new AnchorUser(this.rpc, this.client, { session })];
        }
    }

    /**
     * Resets the authenticator to its initial, default state then calls `init` method
     */
    public reset() {
        this.users = [];
    }

    /**
     * Returns true if the authenticator has errored while initializing.
     */
    public isErrored() {
        return false;
    }

    /**
     * Returns a URL where the user can download and install the underlying authenticator
     * if it is not found by the UAL Authenticator.
     */
    public getOnboardingLink(): string {
        return "https://github.com/greymass/anchor/";
    }

    /**
     * Returns error (if available) if the authenticator has errored while initializing.
     */
    public getError(): UALError | null {
        return null;
    }

    /**
     * Returns true if the authenticator is loading while initializing its internal state.
     */
    public isLoading() {
        return false;
    }

    public getName() {
        return "anchor";
    }

    /**
     * Returns the style of the Button that will be rendered.
     */
    public getStyle(): ButtonStyle {
        return {
            icon: AnchorLogo,
            text: Name,
            textColor: "white",
            background: "#3650A2",
        };
    }

    /**
     * Returns whether or not the button should render based on the operating environment and other factors.
     * ie. If your Authenticator App does not support mobile, it returns false when running in a mobile browser.
     */
    public shouldRender() {
        return !this.isLoading();
    }

    /**
     * Returns whether or not the dapp should attempt to auto login with the Authenticator app.
     * Auto login will only occur when there is only one Authenticator that returns shouldRender() true and
     * shouldAutoLogin() true.
     */
    public shouldAutoLogin() {
        return this.users.length > 0;
    }

    /**
     * Returns whether or not the button should show an account name input field.
     * This is for Authenticators that do not have a concept of account names.
     */
    public async shouldRequestAccountName(): Promise<boolean> {
        return false;
    }

    /**
     * Login using the Authenticator App. This can return one or more users depending on multiple chain support.
     *
     * @param accountName  The account name of the user for Authenticators that do not store accounts (optional)
     */
    public async login(): Promise<User[]> {
        if (this.chains.length > 1) {
            throw new UALAnchorError(
                "UAL-Anchor does not yet support providing multiple chains to UAL. Please initialize the UAL provider with a single chain.",
                UALErrorType.Unsupported,
                null
            );
        }
        try {
            // only call the login method if no users exist, to prevent UI from prompting for login during auto login
            //  some changes to UAL are going to be required to support multiple users
            if (this.users.length === 0) {
                const identity = await this.link.login(this.appName);
                this.users = [new AnchorUser(this.rpc, this.client, identity)];
            }
        } catch (e: any) {
            throw new UALAnchorError(e.message, UALErrorType.Login, e);
        }
        return this.users;
    }

    /**
     * Logs the user out of the dapp. This will be strongly dependent on each Authenticator app's patterns.
     */
    public async logout(): Promise<void> {
        // Ensure a user exists to logout
        if (this.users.length) {
            // retrieve the current user
            const [user] = this.users;
            // retrieve the auth from the current user
            const {
                session: { auth },
            } = user;
            // remove the session from anchor-link
            await this.link.removeSession(this.appName, auth, this.chainId);
        }
        // reset the authenticator
        this.reset();
    }

    /**
     * Returns true if user confirmation is required for `getKeys`
     */
    public requiresGetKeyConfirmation(): boolean {
        return false;
    }
}

// Aided with basic GitHub coding tools

/**
 * Docker Service - Manages Docker containers and Docker Compose operations
 * Quản lý Docker containers và các thao tác Docker Compose
 */

var Tool = require('@modelcontextprotocol/sdk/types.js').Tool;
var Service = require('./base-service.js').Service;
var spawn = require('child_process').spawn;
var exec = require('child_process').exec;
var promisify = require('util').promisify;
var path = require('path');
var fs = require('fs/promises');

var execAsync = promisify(exec);

/**
 * Docker Container Status
 * Trạng thái của Docker container
 */
export interface ContainerStatus {
    name: string;
    status: 'running' | 'stopped' | 'paused' | 'restarting' | 'removing' | 'created' | 'exited' | 'dead';
    health: 'healthy' | 'unhealthy' | 'starting' | 'none';
    uptime: string;
    ports: string[];
    image: string;
}

/**
 * Docker Compose Service Definition
 * Định nghĩa service trong Docker Compose
 */
export interface ComposeService {
    name: string;
    image: string;
    ports: string[];
    volumes: string[];
    environment: Record<string, string>;
    healthCheck?: {
        test: string[];
        interval: string;
        timeout: string;
        retries: number;
    };
}

/**
 * Docker Service Implementation
 * Implements Docker container management operations
 */
class DockerService implements Service {
    readonly namespace = 'docker';
    readonly name = 'Docker Management Service';
    readonly version = '1.0.0';
    readonly description = 'Manages Docker containers, images, and Docker Compose operations';

    private composePath: string;
    private projectName: string;

    constructor(composePath?: string, projectName?: string) {
        this.composePath = composePath || path.join(process.cwd(), 'docker-compose.yml');
        this.projectName = projectName || 'mcp';
    }

    /**
     * List all available Docker management tools
     * Liệt kê tất cả các công cụ quản lý Docker
     */
    async listTools(): Promise<{ tools: Tool[] }> {
        return {
            tools: [
                {
                    name: 'docker_ps',
                    description: 'List all Docker containers with their status',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            all: {
                                type: 'boolean',
                                description: 'Show all containers (default: false - only running)',
                                default: false
                            }
                        }
                    }
                },
                {
                    name: 'docker_compose_up',
                    description: 'Start Docker Compose services',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            services: {
                                type: 'array',
                                items: { type: 'string' },
                                description: 'Specific services to start (optional - all services if not specified)'
                            },
                            detached: {
                                type: 'boolean',
                                description: 'Run in detached mode',
                                default: true
                            },
                            build: {
                                type: 'boolean',
                                description: 'Build images before starting',
                                default: false
                            }
                        }
                    }
                },
                {
                    name: 'docker_compose_down',
                    description: 'Stop and remove Docker Compose services',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            volumes: {
                                type: 'boolean',
                                description: 'Remove volumes as well',
                                default: false
                            },
                            removeImages: {
                                type: 'string',
                                enum: ['all', 'local', 'none'],
                                description: 'Remove images (all, local, or none)',
                                default: 'none'
                            }
                        }
                    }
                },
                {
                    name: 'docker_compose_restart',
                    description: 'Restart Docker Compose services',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            services: {
                                type: 'array',
                                items: { type: 'string' },
                                description: 'Specific services to restart (optional)'
                            }
                        }
                    }
                }, {
                    name: 'docker_logs',
                    description: 'Get logs from Docker containers',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            container: {
                                type: 'string',
                                description: 'Container name or ID'
                            },
                            tail: {
                                type: 'number',
                                description: 'Number of lines to show from the end of logs',
                                default: 100
                            },
                            follow: {
                                type: 'boolean',
                                description: 'Follow log output',
                                default: false
                            }
                        },
                        required: ['container']
                    }
                },
                {
                    name: 'docker_health_check',
                    description: 'Check health status of all services',
                    inputSchema: {
                        type: 'object',
                        properties: {}
                    }
                }, {
                    name: 'docker_exec',
                    description: 'Execute command in running container',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            container: {
                                type: 'string',
                                description: 'Container name or ID'
                            },
                            command: {
                                type: 'string',
                                description: 'Command to execute'
                            },
                            interactive: {
                                type: 'boolean',
                                description: 'Run in interactive mode',
                                default: false
                            }
                        },
                        required: ['container', 'command']
                    }
                },
                {
                    name: 'docker_stats',
                    description: 'Get resource usage statistics for containers',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            containers: {
                                type: 'array',
                                items: { type: 'string' },
                                description: 'Specific containers to monitor (optional - all if not specified)'
                            }
                        }
                    }
                }
            ]
        };
    }

    /**
     * Execute Docker management tools
     * Thực thi các công cụ quản lý Docker
     */
    async callTool(name: string, args: any): Promise<any> {
        try {
            switch (name) {
                case 'docker_ps':
                    return await this.listContainers(args.all || false);

                case 'docker_compose_up':
                    return await this.composeUp(args.services, args.detached !== false, args.build || false);

                case 'docker_compose_down':
                    return await this.composeDown(args.volumes || false, args.removeImages || 'none');

                case 'docker_compose_restart':
                    return await this.composeRestart(args.services);

                case 'docker_logs':
                    return await this.getLogs(args.container, args.tail || 100, args.follow || false);

                case 'docker_health_check':
                    return await this.healthCheck();

                case 'docker_exec':
                    return await this.execCommand(args.container, args.command, args.interactive || false);

                case 'docker_stats':
                    return await this.getStats(args.containers);

                default:
                    throw new Error("Unknown Docker tool: " + (name) + "");
            }
        } catch (error) {
            throw new Error("Docker tool '" + (name) + "' failed: " + (error instanceof Error ? error.message : String(error)) + "");
        }
    }

  /**
   * List Docker containers
   * Liệt kê các Docker containers
   */  private async listContainers(all: boolean = false): Promise<{ containers: ContainerStatus[] }> {
        var command = all ? 'docker ps -a --format "{{.Names}}\t{{.Status}}\t{{.Ports}}\t{{.Image}}"'
            : 'docker ps --format "{{.Names}}\t{{.Status}}\t{{.Ports}}\t{{.Image}}"';

        var stdout = await.stdout;execAsync(command);
        var lines = stdout.trim().split('\n');

        var containers: ContainerStatus[] = [];
        for (var line of lines) {
            if (line.trim()) {
                var parts = line.split('\t');
                if (parts.length >= 4) {
                    var [name, status, ports, image] = parts;

                    // Get health status
                    var health: ContainerStatus['health'] = 'none';
                    try {
                        var { stdout: healthOutput } = await execAsync("docker inspect --format='{{.State.Health.Status}}' " + (name.trim()) + "");
                        var healthStatus = healthOutput.trim();
                        if (healthStatus && healthStatus !== '<no value>') {
                            health = healthStatus as ContainerStatus['health'];
                        }
                    } catch {
                        // Health check not available
                    }

                    containers.push({
                        name: name.trim(),
                        status: this.parseContainerStatus(status.trim()),
                        health,
                        uptime: status.trim(),
                        ports: ports ? ports.split(',').map(function p { return p.trim(); }) : [],
                        image: image.trim()
                    });
                }
            }
        }

        return { containers };
    }

    /**
     * Start Docker Compose services
     * Khởi động các dịch vụ Docker Compose
     */
    private async composeUp(services?: string[], detached: boolean = true, build: boolean = false): Promise<{ success: boolean; message: string; output: string }> {
        var command = 'docker compose -f "' + (this.composePath) + '"';

        if (build) {
            command += ' up --build';
        } else {
            command += ' up';
        }

        if (detached) {
            command += ' -d';
        }

        if (services && services.length > 0) {
            command += " " + (services.join(' ')) + "";
        }

        try {
            var stdout = await.stdout;
var stderr = await.stderr;execAsync(command);
            return {
                success: true,
                message: "Docker Compose services started successfully",
                output: stdout + stderr
            };
        } catch (error: any) {
            return {
                success: false,
                message: "Failed to start Docker Compose services: " + (error.message) + "",
                output: error.stdout + error.stderr
            };
        }
    }

    /**
     * Stop Docker Compose services
     * Dừng các dịch vụ Docker Compose
     */
    private async composeDown(volumes: boolean = false, removeImages: string = 'none'): Promise<{ success: boolean; message: string; output: string }> {
        var command = 'docker compose -f "' + (this.composePath) + '" down';

        if (volumes) {
            command += ' -v';
        }

        if (removeImages !== 'none') {
            command += " --rmi " + (removeImages) + "";
        }

        try {
            var stdout = await.stdout;
var stderr = await.stderr;execAsync(command);
            return {
                success: true,
                message: 'Docker Compose services stopped successfully',
                output: stdout + stderr
            };
        } catch (error: any) {
            return {
                success: false,
                message: "Failed to stop Docker Compose services: " + (error.message) + "",
                output: error.stdout + error.stderr
            };
        }
    }

    /**
     * Restart Docker Compose services
     * Khởi động lại các dịch vụ Docker Compose
     */
    private async composeRestart(services?: string[]): Promise<{ success: boolean; message: string; output: string }> {
        var command = 'docker compose -f "' + (this.composePath) + '" restart';

        if (services && services.length > 0) {
            command += " " + (services.join(' ')) + "";
        }

        try {
            var stdout = await.stdout;
var stderr = await.stderr;execAsync(command);
            return {
                success: true,
                message: 'Docker Compose services restarted successfully',
                output: stdout + stderr
            };
        } catch (error: any) {
            return {
                success: false,
                message: "Failed to restart Docker Compose services: " + (error.message) + "",
                output: error.stdout + error.stderr
            };
        }
    }

    /**
     * Get container logs
     * Lấy logs từ container
     */
    private async getLogs(container: string, tail: number = 100, follow: boolean = false): Promise<{ logs: string; container: string }> {
        var command = "docker logs --tail " + (tail) + "";

        if (follow) {
            command += ' -f';
        }

        command += " " + (container) + "";

        try {
            var stdout = await.stdout;
var stderr = await.stderr;execAsync(command);
            return {
                container,
                logs: stdout + stderr
            };
        } catch (error: any) {
            throw new Error("Failed to get logs for container " + (container) + ": " + (error.message) + "");
        }
    }

    /**
     * Health check for all services
     * Kiểm tra sức khỏe của tất cả các dịch vụ
     */
    private async healthCheck(): Promise<{ services: Array<{ name: string; status: string; health: string }> }> {
        var containers = await.containers;this.listContainers(false);

        var services = containers.map(function container { return ({
            name: container.name,
            status: container.status,
            health: container.health
        }); });

        return { services };
    }

    /**
     * Execute command in container
     * Thực thi lệnh trong container
     */
    private async execCommand(container: string, command: string, interactive: boolean = false): Promise<{ output: string; container: string; command: string }> {
        var dockerCommand = 'docker exec';

        if (interactive) {
            dockerCommand += ' -it';
        }

        dockerCommand += " " + (container) + " " + (command) + "";

        try {
            var stdout = await.stdout;
var stderr = await.stderr;execAsync(dockerCommand);
            return {
                container,
                command,
                output: stdout + stderr
            };
        } catch (error: any) {
            throw new Error("Failed to execute command in container " + (container) + ": " + (error.message) + "");
        }
    }

    /**
     * Get container resource statistics
     * Lấy thống kê tài nguyên của container
     */
    private async getStats(containers?: string[]): Promise<{ stats: string }> {
        var command = 'docker stats --no-stream --format "table {{.Container}}\t{{.CPUPerc}}\t{{.MemUsage}}\t{{.NetIO}}\t{{.BlockIO}}"';

        if (containers && containers.length > 0) {
            command += " " + (containers.join(' ')) + "";
        }

        try {
            var stdout = await.stdout;execAsync(command);
            return { stats: stdout };
        } catch (error: any) {
            throw new Error("Failed to get container stats: " + (error.message) + "");
        }
    }

    /**
     * Parse container status from Docker output
     * Phân tích trạng thái container từ output của Docker
     */
    private parseContainerStatus(status: string): ContainerStatus['status'] {
        var statusLower = status.toLowerCase();

        if (statusLower.includes('up')) return 'running';
        if (statusLower.includes('exited')) return 'exited';
        if (statusLower.includes('created')) return 'created';
        if (statusLower.includes('restarting')) return 'restarting';
        if (statusLower.includes('removing')) return 'removing';
        if (statusLower.includes('paused')) return 'paused';
        if (statusLower.includes('dead')) return 'dead';

        return 'stopped';
    }

    /**
     * Check if Docker is available
     * Kiểm tra xem Docker có khả dụng không
     */
    async isDockerAvailable(): Promise<boolean> {
        try {
            await execAsync('docker --version');
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Check if Docker Compose is available
     * Kiểm tra xem Docker Compose có khả dụng không
     */
    async isDockerComposeAvailable(): Promise<boolean> {
        try {
            await execAsync('docker compose version');
            return true;
        } catch {
            return false;
        }
    }
}

var number = require('prop-types').number;


export enum CPFCNPJType
{
    CPF = 1,
        CNPJ = 0
}

class CPFCNPJValidator{

    _regexNondigit: RegExp = /\D/g;




    _isRepeatingChar(data:string): boolean{

        return data.split('').every(function (currentChar) { currentChar === data[0]});
    }

    public RemoveNondigits(field:string):string{
        return field.replace(this._regexNondigit,'');
    }

    public validaCPF(_cpf:string):boolean{

        let cpfNumerico = _cpf.replace(this._regexNondigit,'');
        if(!this._isRepeatingChar(cpfNumerico))
        {
            const mod11 = function ( num:number ) { return num % 11; };

            const toSumOfProducts = function ( multiplier:any ) { return ( result:any, num:any, i:any ) =>  result + ( num * multiplier-- ); };

            const getSumOfProducts = function ( list:string[], multiplier:number ) { return list.reduce( toSumOfProducts(multiplier),0); };

            const getValidationDigit = function ( multiplier:any ) { return ( cpf:string[] ) => getDigit(mod11(getSumOfProducts(cpf, multiplier ) ) ); };

            const getDigit = function ( num:any ) { return ( num > 1 )  ? 11 - num  : 0; };

            let CPF = cpfNumerico.slice(0,9).split('');
            const firstDigit = getValidationDigit(10)(CPF).toString();
            const secondDigit = getValidationDigit(11)(CPF.concat(firstDigit)).toString();

            CPF = CPF.concat(firstDigit);
            CPF = CPF.concat(secondDigit);

            return cpfNumerico === CPF.join('');

            console.log("validaCPF");
        }

        return false;
    }

    public isCPF(cpf:string):boolean{
        let cpfNumerico = cpf.replace(this._regexNondigit,'');

        if(cpfNumerico.length == 11)
            return true;

        return false;
    }

    public formataCPF(cpf:string):string{
        console.log("FormataCPF");
        let cpfNumerico = cpf.replace(this._regexNondigit,'');
        let cpfFormatado = cpfNumerico.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/g,'$1.$2.$3-$4');

        return cpfFormatado;
    }

    public validaCNPJ(cnpj:string):boolean{
        console.log("validaCNPJ");

        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');
        if(!this._isRepeatingChar(cnpjNumerico))
        {
            // Cáculo de validação
	        let t = cnpjNumerico.length - 2,
                d = cnpjNumerico.substring(t),
                d1 = parseInt(d.charAt(0)),
                d2 = parseInt(d.charAt(1)),
                calc = function (x:any) {
                    let n = cnpjNumerico.substring(0, x),
                        y = x - 7,
                        s = 0,
                        r = 0

                        for (let i = x; i >= 1; i--) {
                            s += parseInt(n.charAt(x - i)) * y--;
                            if (y < 2)
                                y = 9
                        }

                        r = 11 - s % 11
                        return r > 9 ? 0 : r
                }

            let firstDigit = calc(t).toString();
            let secondDigt = calc(t+1).toString();
            let CNPJDigitos = '';
            CNPJDigitos = CNPJDigitos.concat(firstDigit);
            CNPJDigitos = CNPJDigitos.concat(secondDigt);

            return cnpjNumerico.substring(12) === CNPJDigitos;

        }
        return false;
    }

    public isCNPJ(cnpj:string):boolean{
        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');

        if(cnpjNumerico.length == 14)
            return true;

        return false;
    }

    public formataCNPJ(cnpj:string):string{
        let cnpjNumerico = cnpj.replace(this._regexNondigit,'');
        //88.044.098/0001-20
        let cnpjFormatado = cnpjNumerico.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/,'$1.$2.$3/$4.$5');

        return cnpjFormatado;
    }
}

// Aided with basic GitHub coding tools
var vscode = require('vscode');
var WorkspaceTaskManager = require('./models/task-manager').WorkspaceTaskManager;
var TaskTreeDataProvider = require('./views/task-tree-provider').TaskTreeDataProvider;
var TaskCommands = require('./task-commands').TaskCommands;
var QuickActions = require('./quick-actions').QuickActions;
var WorkspaceCommands = require('./workspace-commands').WorkspaceCommands;
var TaskCodeLensProvider = require('./task-code-lens-provider').TaskCodeLensProvider;
var TaskHoverProvider = require('./task-hover-provider').TaskHoverProvider;
var TaskCompletionProvider = require('./task-completion-provider').TaskCompletionProvider;
var TaskDecorationProvider = require('./task-decoration-provider').TaskDecorationProvider;
var QueryResultPanel = require('./views/query-result-panel').QueryResultPanel;
var Lexer = require('./models/query-lexer').Lexer;
var Parser = require('./models/query-parser').Parser;
var QueryExecutor = require('./models/query-executor').QueryExecutor;
var SavedQueryManager = require('./models/saved-query-manager').SavedQueryManager;
var QueryTreeDataProvider = require('./views/query-tree-provider').QueryTreeDataProvider;
var uuidv4 = require('uuid').v4;

// This function is called when your extension is activated
function activate(context: vscode.ExtensionContext) {
  console.log("VsTasks extension is now active!");

  // Create workspace task manager instance
  var taskManager = new WorkspaceTaskManager();

  // Create tree view provider
  var taskTreeProvider = new TaskTreeDataProvider(taskManager);
  var taskTreeView = vscode.window.createTreeView("vstasks.taskTree", {
    treeDataProvider: taskTreeProvider,
  });

  // --- コマンド登録はTaskCommands/QuickActions/WorkspaceCommandsに一元化 ---

  // Saved Query Sidebar
  var savedQueryManager = new SavedQueryManager(context);
  var queryTreeProvider = new QueryTreeDataProvider(
    savedQueryManager,
    taskManager
  );
  vscode.window.createTreeView("vstasks.queryView", {
    treeDataProvider: queryTreeProvider,
    showCollapseAll: false,
  });

  // Register command: Add/Edit/Delete/Run Saved Query ...（このまま）
  context.subscriptions.push(
    vscode.commands.registerCommand("vstasks.addSavedQuery", async function () {
      var label = await vscode.window.showInputBox({
        prompt: "クエリ名を入力",
      });
      if (!label) {
        return;
      }
      var query = await vscode.window.showInputBox({
        prompt: "クエリ内容を入力",
      });
      if (!query) {
        return;
      }
      savedQueryManager.add({ id: uuidv4(), label, query });
      queryTreeProvider.refresh();
    }),
    vscode.commands.registerCommand("vstasks.editSavedQuery", async function (item) {
      var label = await vscode.window.showInputBox({
        prompt: "新しいクエリ名",
        value: item.query.label,
      });
      if (!label) {
        return;
      }
      var query = await vscode.window.showInputBox({
        prompt: "新しいクエリ内容",
        value: item.query.query,
      });
      if (!query) {
        return;
      }
      savedQueryManager.update(item.query.id, { label, query });
      queryTreeProvider.refresh();
    }),
    vscode.commands.registerCommand(
      "vstasks.deleteSavedQuery",
      async function (item) {
        var ok = await vscode.window.showQuickPick(["はい", "いいえ"], {
          placeHolder: "本当に削除しますか?",
        });
        if (ok === "はい") {
          savedQueryManager.remove(item.query.id);
          queryTreeProvider.refresh();
        }
      }
    ),
    vscode.commands.registerCommand("vstasks.runSavedQuery", async function (query) {
      try {
        // Aided with basic GitHub coding tools
        // Accept both string and object
        var queryText = typeof query === "string" ? query : query?.query;
        if (!queryText) {
          vscode.window.showErrorMessage("クエリが見つかりません");
          return;
        }
        var lexer = new Lexer(queryText);
        var parser = new Parser(lexer);
        var ast = parser.parseQuery();
        var executor = new QueryExecutor(taskManager.getAllTasks());
        var result = executor.executeQuery(ast);
        var panel = new QueryResultPanel(context.extensionUri);
        panel.show(result);
      } catch (err) {
        vscode.window.showErrorMessage("クエリ実行エラー: " + (err) + "");
      }
    }),
    vscode.commands.registerCommand("vstasks.completeTask", async function (item) {
      // itemはTaskTreeItemまたはQueryTreeItem
      var task = item?.task;
      if (!task && item?.type === "task") {
        task = item.task;
      }
      if (!task && item?.type === "queryTask") {
        task = item.task;
      }
      if (!task) {
        vscode.window.showErrorMessage("タスク情報が取得できません");
        return;
      }
      if (task.status === "done") {
        vscode.window.showInformationMessage("すでに完了済みです");
        return;
      }
      // ステータスを完了に変更
      var taskCommands = new TaskCommands(taskManager);
      await taskCommands.toggleTaskStatus(task.id);
      vscode.window.showInformationMessage("タスクを完了にしました");
    }),
    vscode.commands.registerCommand(
      "vstasks.openTaskFile",
      async function (filePath: string, lineNumber: number) {
        if (!filePath) {
          vscode.window.showErrorMessage("ファイルパスがありません");
          return;
        }
        try {
          var doc = await vscode.workspace.openTextDocument(filePath);
          var editor = await vscode.window.showTextDocument(doc, {
            preview: false,
          });
          if (typeof lineNumber === "number" && lineNumber >= 0) {
            var pos = new vscode.Position(lineNumber, 0);
            editor.selection = new vscode.Selection(pos, pos);
            editor.revealRange(
              new vscode.Range(pos, pos),
              vscode.TextEditorRevealType.InCenter
            );
          }
        } catch (e) {
          vscode.window.showErrorMessage("ファイルを開けませんでした: " + (e) + "");
        }
      }
    )
  );

  // Setup workspace file watcher for markdown files
  var mdWatcher = vscode.workspace.createFileSystemWatcher("**/*.md");
  var markdownWatcher =
    vscode.workspace.createFileSystemWatcher("**/*.markdown");

  // File watcher events
  mdWatcher.onDidChange(function (uri: vscode.Uri) {
    console.log("File changed: " + (uri.fsPath) + "");
    taskManager.scanFile(uri);
  });

  mdWatcher.onDidCreate(function (uri: vscode.Uri) {
    console.log("New file created: " + (uri.fsPath) + "");
    taskManager.scanFile(uri);
  });

  mdWatcher.onDidDelete(function (uri: vscode.Uri) {
    console.log("File deleted: " + (uri.fsPath) + "");
    taskManager.removeTasks(uri.fsPath);
  });

  // Register watchers for .markdown files too
  markdownWatcher.onDidChange(function (uri: vscode.Uri) {
    console.log("File changed: " + (uri.fsPath) + "");
    taskManager.scanFile(uri);
  });

  markdownWatcher.onDidCreate(function (uri: vscode.Uri) {
    console.log("New file created: " + (uri.fsPath) + "");
    taskManager.scanFile(uri);
  });

  markdownWatcher.onDidDelete(function (uri: vscode.Uri) {
    console.log("File deleted: " + (uri.fsPath) + "");
    taskManager.removeTasks(uri.fsPath);
  });

  // Register editor features for markdown
  context.subscriptions.push(
    vscode.languages.registerCodeLensProvider(
      { language: "markdown" },
      new TaskCodeLensProvider()
    ),
    vscode.languages.registerHoverProvider(
      { language: "markdown" },
      new TaskHoverProvider()
    ),
    vscode.languages.registerCompletionItemProvider(
      { language: "markdown" },
      new TaskCompletionProvider(),
      "#",
      "-",
      "[",
      "⏫",
      "⏳",
      "📅"
    )
  );
  // Optionally: update decorations on active editor change
  var decoProvider = new TaskDecorationProvider();
  vscode.window.onDidChangeActiveTextEditor(function (editor) {
    if (editor && editor.document.languageId === "markdown") {
      decoProvider.updateDecorations(editor);
    }
  });
  vscode.workspace.onDidChangeTextDocument(function (e) {
    var editor = vscode.window.activeTextEditor;
    if (
      editor &&
      editor.document === e.document &&
      editor.document.languageId === "markdown"
    ) {
      decoProvider.updateDecorations(editor);
    }
  });

  // Scan workspace for tasks on activation
  taskManager.scanWorkspace().then(function () {
    console.log("Initial workspace scan complete");
  });

  // Register new command classes
  var taskCommands = new TaskCommands(taskManager);
  taskCommands.registerCommands(context);
  var quickActions = new QuickActions(taskManager);
  quickActions.registerCommands(context);
  var workspaceCommands = new WorkspaceCommands(taskManager);
  workspaceCommands.registerCommands(context);

  // Register everything to be disposed when extension is deactivated
  context.subscriptions.push(mdWatcher, markdownWatcher, taskTreeView);
}

// This function is called when your extension is deactivated
function deactivate() {
  console.log("VsTasks extension is now deactivated!");
}

