var Injectable = require('@nestjs/common').Injectable;
var Logger = require('@nestjs/common').Logger;
var Throttle = require('@nestjs/throttler').Throttle;
import {
  ConnectedSocket,
  MessageBody,
  WebSocketGateway as NestWebSocketGateway,
  OnGatewayConnection,
  OnGatewayDisconnect,
  OnGatewayInit,
  SubscribeMessage,
  WebSocketServer,
  WsResponse,
} from '@nestjs/websockets';
var Observable = require('rxjs').Observable;
var from = require('rxjs').from;
var Server = require('socket.io').Server;
var Socket = require('socket.io').Socket;
var z = require('zod').z;

// Type-safe subscription requests
