var IDiscordMessage = require('./discordtypes').IDiscordMessage;
var IDiscordMessageEmbed = require('./discordtypes').IDiscordMessageEmbed;
var markdown = require('discord-markdown');
var escapeHtml = require('escape-html');
var Util = require('./util').Util;

var MATRIX_TO_LINK = "https://matrix.to/#/";
// somehow the regex works properly if it isn't global
// as we replace the match fully anyways this shouldn't be an issue
var MXC_INSERT_REGEX = /\x01emoji\x01(\w+)\x01([01])\x01([0-9]*)\x01/;
var NAME_MXC_INSERT_REGEX_GROUP = 1;
var ANIMATED_MXC_INSERT_REGEX_GROUP = 2;
var ID_MXC_INSERT_REGEX_GROUP = 3;
var EMOJI_SIZE = 32;
var MAX_EDIT_MSG_LENGTH = 50;

// same as above, no global flag here, too
var CHANNEL_INSERT_REGEX = /\x01chan\x01([0-9]*)\x01/;
var ID_CHANNEL_INSERT_REGEX = 1;

// same as above, no global flag here, too
var USER_INSERT_REGEX = /\x01user\x01([0-9]*)\x01/;
var ID_USER_INSERT_REGEX = 1;

export interface IDiscordMessageParserEntity {
    mxid: string;
    name: string;
}

export interface IDiscordMessageParserCallbacks {
    getUser: function (id: string) { return Promise<IDiscordMessageParserEntity | null>; };
    getChannel: function (id: string) { return Promise<IDiscordMessageParserEntity | null>; };
    getEmoji: function (name: string, animated: boolean, id: string) { return Promise<string | null>; };
}

export interface IDiscordMessageParserOpts {
    callbacks: IDiscordMessageParserCallbacks;
}

export interface IDiscordMessageParserResult {
    formattedBody: string;
    body: string;
    msgtype: string;
}

interface ISpoilerNode {
    content: string;
}

interface IDiscordNode {
    id: string;
}

interface IEmojiNode extends IDiscordNode {
    animated: boolean;
    name: string;
}

class DiscordMessageParser {
    public async FormatMessage(
        opts: IDiscordMessageParserOpts,
        msg: IDiscordMessage,
    ): Promise<IDiscordMessageParserResult> {
        var result: IDiscordMessageParserResult = {
            body: "",
            msgtype: "",
            formattedBody: "",
        };

        var content = msg.content;

        // for the formatted body we need to parse markdown first
        // as else it'll HTML escape the result of the discord syntax
        var contentPostmark = markdown.toHTML(content, {
            discordCallback: this.getDiscordParseCallbacksHTML(opts, msg),
            isBot: msg.author ? msg.author.bot : false,
            noExtraSpanTags: true,
            noHighlightCode: true,
        });

        // parse the plain text stuff
        content = markdown.toHTML(content, {
            discordCallback: this.getDiscordParseCallbacks(opts, msg),
            discordOnly: true,
            escapeHTML: false,
            isBot: msg.author ? msg.author.bot : false,
            noExtraSpanTags: true,
            noHighlightCode: true,
        });
        content = this.InsertEmbeds(opts, content, msg);
        content = await this.InsertMxcImages(opts, content, msg);
        content = await this.InsertUserPills(opts, content, msg);
        content = await this.InsertChannelPills(opts, content, msg);

        // parse postmark stuff
        contentPostmark = this.InsertEmbedsPostmark(opts, contentPostmark, msg);
        contentPostmark = await this.InsertMxcImages(opts, contentPostmark, msg, true);
        contentPostmark = await this.InsertUserPills(opts, contentPostmark, msg, true);
        contentPostmark = await this.InsertChannelPills(opts, contentPostmark, msg, true);

        result.body = content;
        result.formattedBody = contentPostmark;
        result.msgtype = msg.author.bot ? "m.notice" : "m.text";
        return result;
    }

    public async FormatEdit(
        opts: IDiscordMessageParserOpts,
        oldMsg: IDiscordMessage,
        newMsg: IDiscordMessage,
        link?: string,
    ): Promise<IDiscordMessageParserResult> {
        oldMsg.embeds = []; // we don't want embeds on old msg
        var oldMsgParsed = await this.FormatMessage(opts, oldMsg);
        var newMsgParsed = await this.FormatMessage(opts, newMsg);
        var result: IDiscordMessageParserResult = {
            body: "*edit:* ~~" + (oldMsgParsed.body) + "~~ -> " + (newMsgParsed.body) + "",
            msgtype: newMsgParsed.msgtype,
            formattedBody: "",
        };
        oldMsg.content = "*edit:* ~~" + (oldMsg.content) + "~~ -> " + (newMsg.content) + "";
        var linkStart = link ? '<a href="' + (escapeHtml(link)) + '">' : "";
        var linkEnd = link ? "</a>" : "";
        if (oldMsg.content.includes("\n") || newMsg.content.includes("\n")
            || newMsg.content.length > MAX_EDIT_MSG_LENGTH) {
            result.formattedBody = "<p>" + (linkStart) + "<em>edit:</em>" + (linkEnd) + "</p><p><del>" + (oldMsgParsed.formattedBody) + "" +
                "</del></p><hr><p>" + (newMsgParsed.formattedBody) + "</p>";
        } else {
            result.formattedBody = "" + (linkStart) + "<em>edit:</em>" + (linkEnd) + " <del>" + (oldMsgParsed.formattedBody) + "</del>" +
                " -&gt; " + (newMsgParsed.formattedBody) + "";
        }
        return result;
    }

    public InsertEmbeds(opts: IDiscordMessageParserOpts, content: string, msg: IDiscordMessage): string {
        for (var embed of msg.embeds) {
            if (embed.title === undefined && embed.description === undefined) {
                continue;
            }
            if (this.isEmbedInBody(opts, msg, embed)) {
                continue;
            }
            var embedContent = content ? "\n\n----" : "";
            var embedTitle = embed.url ? "[" + (embed.title) + "](" + (embed.url) + ")" : embed.title;
            if (embedTitle) {
                embedContent += "\n##### " + embedTitle; // h5 is probably best.
            }
            if (embed.author && embed.author.name) {
                embedContent += "\n**" + (escapeHtml(embed.author.name)) + "**";
            }
            if (embed.description) {
                embedContent += "\n" + markdown.toHTML(embed.description, {
                    discordCallback: this.getDiscordParseCallbacks(opts, msg),
                    discordOnly: true,
                    escapeHTML: false,
                    isBot: msg.author ? msg.author.bot : false,
                    noExtraSpanTags: true,
                    noHighlightCode: true,
                });
            }
            if (embed.fields) {
                for (var field of embed.fields) {
                    embedContent += "\n**" + (field.name) + "**\n";
                    embedContent += markdown.toHTML(field.value, {
                        discordCallback: this.getDiscordParseCallbacks(opts, msg),
                        discordOnly: true,
                        escapeHTML: false,
                        isBot: msg.author ? msg.author.bot : false,
                        noExtraSpanTags: true,
                        noHighlightCode: true,
                    });
                }
            }
            if (embed.image) {
                embedContent += "\nImage: " + embed.image.url;
            }
            if (embed.footer) {
                embedContent += "\n" + markdown.toHTML(embed.footer.text, {
                    discordCallback: this.getDiscordParseCallbacks(opts, msg),
                    discordOnly: true,
                    escapeHTML: false,
                    isBot: msg.author ? msg.author.bot : false,
                    noExtraSpanTags: true,
                    noHighlightCode: true,
                });
            }
            content += embedContent;
        }
        return content;
    }

    public InsertEmbedsPostmark(opts: IDiscordMessageParserOpts, content: string, msg: IDiscordMessage): string {
        for (var embed of msg.embeds) {
            if (embed.title === undefined && embed.description === undefined) {
                continue;
            }
            if (this.isEmbedInBody(opts, msg, embed)) {
                continue;
            }
            var embedContent = content ? "<hr>" : "";
            var embedTitle = embed.url ?
                '<a href="' + (escapeHtml(embed.url)) + '">' + (escapeHtml(embed.title)) + "</a>"
                : (embed.title ? escapeHtml(embed.title) : undefined);
            if (embedTitle) {
                embedContent += "<h5>" + (embedTitle) + "</h5>"; // h5 is probably best.
            }
            if (embed.author && embed.author.name) {
                embedContent += "<strong>" + (escapeHtml(embed.author.name)) + "</strong><br>";
            }
            if (embed.description) {
                embedContent += "<p>";
                embedContent += markdown.toHTML(embed.description, {
                    discordCallback: this.getDiscordParseCallbacksHTML(opts, msg),
                    embed: true,
                    isBot: msg.author ? msg.author.bot : false,
                    noExtraSpanTags: true,
                    noHighlightCode: true,
                }) + "</p>";
            }
            if (embed.fields) {
                for (var field of embed.fields) {
                    embedContent += "<p><strong>" + (escapeHtml(field.name)) + "</strong><br>";
                    embedContent += markdown.toHTML(field.value, {
                        discordCallback: this.getDiscordParseCallbacks(opts, msg),
                        embed: true,
                        isBot: msg.author ? msg.author.bot : false,
                        noExtraSpanTags: true,
                        noHighlightCode: true,
                    }) + "</p>";
                }
            }
            if (embed.image) {
                var imgUrl = escapeHtml(embed.image.url);
                embedContent += '<p>Image: <a href="' + (imgUrl) + '">' + (imgUrl) + "</a></p>";
            }
            if (embed.footer) {
                embedContent += "<p>";
                embedContent += markdown.toHTML(embed.footer.text, {
                    discordCallback: this.getDiscordParseCallbacksHTML(opts, msg),
                    embed: true,
                    isBot: msg.author ? msg.author.bot : false,
                    noExtraSpanTags: true,
                    noHighlightCode: true,
                }) + "</p>";
            }
            content += embedContent;
        }
        return content;
    }

    public InsertUser(opts: IDiscordMessageParserOpts, node: IDiscordNode, msg: IDiscordMessage): string {
        // unfortunately these callbacks are sync, so we flag our channel with some special stuff
        // and later on grab the real channel pill async
        var FLAG = "\x01";
        return "" + (FLAG) + "user" + (FLAG) + "" + (node.id) + "" + (FLAG) + "";
    }

    public InsertSpoiler(opts: IDiscordMessageParserOpts, node: ISpoilerNode, html: boolean = false): string {
        // matrix spoilers are still in MSC stage
        // see https://github.com/matrix-org/matrix-doc/pull/2010
        if (!html) {
            return "(Spoiler: " + (node.content) + ")";
        }
        return "<span data-mx-spoiler>" + (node.content) + "</span>";
    }

    public InsertChannel(opts: IDiscordMessageParserOpts, node: IDiscordNode): string {
        // unfortunately these callbacks are sync, so we flag our channel with some special stuff
        // and later on grab the real channel pill async
        var FLAG = "\x01";
        return "" + (FLAG) + "chan" + (FLAG) + "" + (node.id) + "" + (FLAG) + "";
    }

    public InsertRole(
        opts: IDiscordMessageParserOpts,
        node: IDiscordNode,
        msg: IDiscordMessage,
        html: boolean = false,
    ): string {
        var id = node.id;
        var role = msg.guild ? (msg.guild.roles.resolve || msg.guild.roles.get)!.bind(msg.guild.roles)(id) : null;
        if (!role) {
            return html ? "&lt;@&amp;" + (id) + "&gt;" : "<@&" + (id) + ">";
        }
        if (!html) {
            return "@" + (role.name) + "";
        }
        var color = Util.NumberToHTMLColor(role.color);
        return '<span data-mx-color="' + (color) + '"><strong>@' + (escapeHtml(role.name)) + "</strong></span>";
    }

    public InsertEmoji(opts: IDiscordMessageParserOpts, node: IEmojiNode): string {
        // unfortunately these callbacks are sync, so we flag our url with some special stuff
        // and later on grab the real url async
        var FLAG = "\x01";
        return "" + (FLAG) + "emoji" + (FLAG) + "" + (node.name) + "" + (FLAG) + "" + (node.animated ? 1 : 0) + "" + (FLAG) + "" + (node.id) + "" + (FLAG) + "";
    }

    public InsertRoom(opts: IDiscordMessageParserOpts, msg: IDiscordMessage, def: string): string {
        return (msg.mentions && msg.mentions.everyone) || msg.mention_everyone ? "@room" : def;
    }

    public async InsertMxcImages(
        opts: IDiscordMessageParserOpts,
        content: string,
        msg: IDiscordMessage,
        html: boolean = false,
    ): Promise<string> {
        var results = MXC_INSERT_REGEX.exec(content);
        while (results !== null) {
            var name = results[NAME_MXC_INSERT_REGEX_GROUP];
            var animated = results[ANIMATED_MXC_INSERT_REGEX_GROUP] === "1";
            var id = results[ID_MXC_INSERT_REGEX_GROUP];
            var replace = "";
            var nameHtml = escapeHtml(name);
            var mxcUrl = await opts.callbacks.getEmoji(name, animated, id);
            if (mxcUrl) {
                if (html) {
                    replace = '<img alt=":' + (nameHtml) + ':" title=":' + (nameHtml) + ':" ' +
                        'height="' + (EMOJI_SIZE) + '" src="' + (mxcUrl) + '" data-mx-emoticon />';
                } else {
                    replace = ":" + (name) + ":";
                }
            } else {
                if (html) {
                    replace = "&lt;" + (animated ? "a" : "") + ":" + (nameHtml) + ":" + (id) + "&gt;";
                } else {
                    replace = "<" + (animated ? "a" : "") + ":" + (name) + ":" + (id) + ">";
                }
            }
            content = content.replace(results[0], replace);
            results = MXC_INSERT_REGEX.exec(content);
        }
        return content;
    }

    public async InsertUserPills(
        opts: IDiscordMessageParserOpts,
        content: string,
        msg: IDiscordMessage,
        html: boolean = false,
    ): Promise<string> {
        var results = USER_INSERT_REGEX.exec(content);
        while (results !== null) {
            var id = results[ID_USER_INSERT_REGEX];
            var user = await opts.callbacks.getUser(id);
            var replace = "";
            if (user) {
                replace = html ? '<a href="' + (MATRIX_TO_LINK) + "" + (escapeHtml(user.mxid)) + '">' +
                    "" + (escapeHtml(user.name)) + "</a>" : "" + (user.name) + " (" + (user.mxid) + ")";
            } else {
                replace = html ? "&lt;@" + (escapeHtml(id)) + "&gt;" : "<@" + (id) + ">";
            }
            content = content.replace(results[0], replace);
            results = USER_INSERT_REGEX.exec(content);
        }
        return content;
    }

    public async InsertChannelPills(
        opts: IDiscordMessageParserOpts,
        content: string,
        msg: IDiscordMessage,
        html: boolean = false,
    ): Promise<string> {
        var results = CHANNEL_INSERT_REGEX.exec(content);
        while (results !== null) {
            var id = results[ID_CHANNEL_INSERT_REGEX];
            var channel = await opts.callbacks.getChannel(id);
            var replace = "";
            if (channel) {
                var name = "#" + channel.name;
                replace = html ? '<a href="' + (MATRIX_TO_LINK) + "" + (escapeHtml(channel.mxid)) + '">' +
                    "" + (escapeHtml(name)) + "</a>" : name;
            } else {
                replace = html ? "&lt;#" + (escapeHtml(id)) + "&gt;" : "<#" + (id) + ">";
            }
            content = content.replace(results[0], replace);
            results = CHANNEL_INSERT_REGEX.exec(content);
        }
        return content;
    }

    private isEmbedInBody(opts: IDiscordMessageParserOpts, msg: IDiscordMessage, embed: IDiscordMessageEmbed): boolean {
        if (!embed.url) {
            return false;
        }
        var url = embed.url;
        if (url.substr(url.length - 1) === "/") {
            url = url.substr(0, url.length - 1);
        }
        if (msg.content.includes(url)) {
            return true;
        }
        // alright, let's special-case youtu.be as it is meh
        // match for youtube URLs the video ID part
        var matchesFromUrl = url.match(/^https?:\/\/(?:www\.)youtube\.com\/watch\?.*v=([^&]+)/);
        if (matchesFromUrl) {
            var matchesFromContent = msg.content.match(/https?:\/\/youtu\.be\/([^\/? ]+)/);
            if (matchesFromContent && matchesFromUrl[1] === matchesFromContent[1]) {
                // okay, said youtube link is already in
                return true;
            }
        }
        return false;
    }

    private getDiscordParseCallbacks(opts: IDiscordMessageParserOpts, msg: IDiscordMessage) {
        return {
            channel: function (node) { return this.InsertChannel(opts, node); }, // are post-inserted
            emoji: function (node) { return this.InsertEmoji(opts, node); }, // are post-inserted
            everyone: function (_) { return this.InsertRoom(opts, msg, "@everyone"); },
            here: function (_) { return this.InsertRoom(opts, msg, "@here"); },
            role: function (node) { return this.InsertRole(opts, node, msg); },
            spoiler: function (node) { return this.InsertSpoiler(opts, node); },
            user: function (node) { return this.InsertUser(opts, node, msg); },
        };
    }

    private getDiscordParseCallbacksHTML(opts: IDiscordMessageParserOpts, msg: IDiscordMessage) {
        return {
            channel: function (node) { return this.InsertChannel(opts, node); }, // are post-inserted
            emoji: function (node) { return this.InsertEmoji(opts, node); }, // are post-inserted
            everyone: function (_) { return this.InsertRoom(opts, msg, "@everyone"); },
            here: function (_) { return this.InsertRoom(opts, msg, "@here"); },
            role: function (node) { return this.InsertRole(opts, node, msg, true); },
            spoiler: function (node) { return this.InsertSpoiler(opts, node, true); },
            user: function (node) { return this.InsertUser(opts, node, msg); },
        };
    }
}

var NextRequest = require('next/server').NextRequest;
var createIntlMiddleware = require('next-intl/middleware');
var locales = require('./i18n').locales;
var defaultLocale = require('./i18n').defaultLocale;
var createMiddlewareClient = require('@supabase/auth-helpers-nextjs').createMiddlewareClient;

// Create the i18n middleware configuration
const handleI18nRouting = createIntlMiddleware({
  locales: locales,
  defaultLocale: defaultLocale,
  localePrefix: 'as-needed', // Adjust as needed ('always', 'never', 'as-needed')
});

export async function middleware(req: NextRequest) {
  // --- Step 1: Handle Internationalization Routing ---
  const intlResponse = handleI18nRouting(req);

  // --- Step 2: Handle Supabase Session Management ---
  // Create a Supabase client tailored for middleware
  const supabase = createMiddlewareClient({ req, res: intlResponse });

  // Refresh session if expired - required for Server Components
  // https://supabase.com/docs/guides/auth/auth-helpers/nextjs#managing-session-with-middleware
  // This will update the session cookie if needed.
  await supabase.auth.getSession();

  // --- Step 3: (Optional) Route Protection ---
  // You can add route protection logic here if desired, similar to the previous Auth.js example,
  // but using Supabase session data.
  // Example:
  // var { data: { session } } = await supabase.auth.getSession();
  // var pathname = req.nextUrl.pathname;
  // var isProtectedRoute = pathname.startsWith('/dashboard'); // Check if path needs auth
  //
  // if (isProtectedRoute && !session) {
  //   // Redirect unauthenticated users to sign-in page
  //   var locale = intlResponse.headers.get('x-next-intl-locale') || defaultLocale;
  //   var signInUrl = new URL(`/${locale}/sign-in`, req.url);
  //   signInUrl.searchParams.set('next', pathname); // Add redirect path after login
  //   return NextResponse.redirect(signInUrl);
  // }

  // Return the response object (potentially modified by i18n routing)
  // The Supabase client automatically handles setting/updating cookies on the response.
  return intlResponse;
}

// Configuration for middleware path matching
const config = {
  matcher: [
    // Skip internal paths and static assets
    '/((?!api|_next/static|_next/image|favicon.ico|assets/).*)',
    // Include the root path for locale redirection
    '/',
  ],
};

// Aided with basic GitHub coding tools
var createServerClient = require('@supabase/ssr').createServerClient;
var type = require('@supabase/ssr').type;
var CookieOptions = require('@supabase/ssr').CookieOptions;
var cookies = require('next/headers').cookies;
var createSupabaseClient = require('@supabase/supabase-js').createClient;

function createClient() {
  var cookieStore = cookies()

  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        get(name: string) {
          return cookieStore.get(name)?.value
        },        set(name: string, value: string, options: CookieOptions) {
          try {
            cookieStore.set({ name, value, ...options })
          } catch {
            // The `set` method was called from a Server Component.
            // This can be ignored if you have middleware refreshing
            // user sessions.
          }
        },
        remove(name: string, options: CookieOptions) {
          try {
            cookieStore.set({ name, value: '', ...options })
          } catch {
            // The `delete` method was called from a Server Component.
            // This can be ignored if you have middleware refreshing
            // user sessions.
          }
        },
      },
    }
  )
}

// Service role client for admin operations (bypasses RLS)
function createServiceClient() {
  return createSupabaseClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
    {
      auth: {
        autoRefreshToken: false,
        persistSession: false
      }
    }
  )
}

