var Console = require('./wasa').Console;

// ANSI Escape
var ESC: string = "\u001b[";

// Ansi Color Codes
var GREEN: string = ESC + "32m";
var WHITE: string = ESC + "37m";
var RED: string = ESC + "31m";
var CYAN: string = ESC + "36m";
var RESET: string = ESC + "0m";

// Ansi Cursor Codes
var HIDE_CURSOR: string = ESC + "?25h";

function printColor(value: string, color: string): void {
  Console.write(color + value + RESET, false);
}

function flushConsole(): void {
  Console.write(ESC + "2J", false);
}

// https://github.com/nojvek/matrix-rain/blob/master/ansi.js
function moveCursorToPosition(column: i32, row: i32): void {
  var cursorPosition: string =
    ESC + row.toString() + ";" + column.toString() + "H";
  Console.write(cursorPosition, false);

  // Hide the cursor
  Console.write(HIDE_CURSOR, false);
}

var crypto = require('crypto');
var shuffleStr = require('../generator').shuffleStr;

// ENCRYPT DATA AND RETURN THE IV... MUST STORE THE HASH AND IV TOGETHER
function encrypt(data: any, key?: string | Buffer): { iv: Buffer, encrypted: string } {
  let iv = crypto.randomBytes(16);
  key = process.env.CRYPTO_SECRET_KEY ? Buffer.from(process.env.CRYPTO_SECRET_KEY) : Buffer.isBuffer(key) ? key : Buffer.from(key);
  let cipher = crypto.createCipheriv('aes-256-ecb', key, iv);
  let encrypted = cipher.update(data, 'utf8', 'base64');
  encrypted += cipher.final('base64');
  return { iv, encrypted };
}

// DECRYPT DATA WITH AN IV
function decrypt(data: any, iv: Buffer, key?: string | Buffer): string {
  key = process.env.CRYPTO_SECRET_KEY ? Buffer.from(process.env.CRYPTO_SECRET_KEY) : Buffer.isBuffer(key) ? key : Buffer.from(key);
  let decipher = crypto.createDecipheriv('aes-256-ecb', key, iv);
  let decrypted = decipher.update(data, 'base64', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}
