}

function initAuth({ req }, db) {
  const getUser = function (fail = false) { return getAuthUserFromReq(req, db, fail)

  return {
    getUser,
    getUserId: () => getUser().then(user => user.id),
    maybeGetUser: () => getUser(false),
    generateToken: generateToken
  }; }}

export async function getAuthUserFromReq(req: any, db: any, shouldFail = true) {
  var authorization = req.headers.authorization;const noAuthorization = !authorization || authorization.indexOf('Bearer') === -1

  if (noAuthorization && shouldFail) throw new AuthenticationError('You must supply a JWT for authorization!')
  else if (noAuthorization) return null 

  // cache user via req object in case there are repeat calls to $getUser
  if (req.user) return req.user 

  const token = authorization.replace('Bearer ', '')
  const user = await getAuthUser(db.$connection, token)
  req.user = user

  return req.user
}

export async function getAuthUser(connection: any, token: any) {
  let userId
  try {
    userId = jwt.verify(token, getAppKey()).userId
  } catch (err) {
    throw new ForbiddenError('You are not authorized.')
  }

  const user = await connection('users').where('id', userId).first()
  if (!user) throw new AuthenticationError('Encrypted user does not exist.')
  return user
}

function generateToken (userId) {
  return jwt.sign({ userId }, getAppKey())
}

import deepEqual = require('deep-equal');

type FetchFunction = typeof window.fetch;

type CreateUseFetch = function (fetch?: FetchFunction) { return UseFetch; };

interface Export extends UseFetch {
  createUseFetch: CreateUseFetch;
  default: UseFetch;
}

interface FetchCache {
  bodyUsed?: boolean;
  contentType?: null | string;
  fetch?: Promise<void>;
  error?: any;
  headers?: Headers;
  init: RequestInit | undefined;
  input: RequestInfo;
  ok?: boolean;
  redirected?: boolean;
  response?: any;
  status?: number;
  statusText?: string;
  url?: string;
}

type FetchResponse = Object | string;

interface FetchResponseMetadata {
  bodyUsed: boolean;
  contentType: null | string;
  headers: Headers;
  ok: boolean;
  redirected: boolean;
  response: FetchResponse;
  status: number;
  statusText: string;
  url: string;
}

interface Options {
  lifespan?: number;
  metadata?: boolean;
}

interface OptionsWithMetadata extends Options {
  metadata: true;
}

interface OptionsWithoutMetadata extends Options {
  metadata?: false;
}

interface UseFetch {
  (
    input: RequestInfo,
    init?: RequestInit | undefined,
    options?: number | OptionsWithoutMetadata,
  ): FetchResponse;
  (
    input: RequestInfo,
    init: RequestInit | undefined,
    options: OptionsWithMetadata,
  ): FetchResponseMetadata;
}

const getDefaultFetchFunction = (): function FetchFunction {
  if (typeof window === 'undefined') {
    return (): Promise<Response> => {
      return Promise.reject(
        new Error('Cannot find `window`. Use `createUseFetch` to provide a custom `fetch` function.'),
      );
    };
  }
  if (typeof window.fetch === 'undefined') {
    return (): Promise<Response> => {
      return Promise.reject(
        new Error('Cannot find `window.fetch`. Use `createUseFetch` to provide a custom `fetch` function.'),
      );
    };
  }
  return window.fetch;
};

const createUseFetch: CreateUseFetch = (
  fetch: FetchFunction = getDefaultFetchFunction(),
): function UseFetch {
  // Create a set of caches for this hook.
  const caches: FetchCache[] = [];

  function useFetch(
    input: RequestInfo,
    init?: RequestInit | undefined,
    options?: number | OptionsWithoutMetadata,
  ): FetchResponse;
  function useFetch(
    input: RequestInfo,
    init: RequestInit | undefined,
    options: OptionsWithMetadata,
  ): FetchResponseMetadata;
  function useFetch(
    input: RequestInfo,
    init?: RequestInit | undefined,
    options: number | Options = 0,
  ): FetchResponse | FetchResponseMetadata {

    if (typeof options === 'number') {
      return useFetch(input, init, { lifespan: options });
    }

    var metadata = options.metadata;
var lifespan = options.lifespan;

    // Check each cache by this useFetch hook.
    for (const cache of caches) {

      // If this cache matches the request,
      if (
        deepEqual(input, cache.input) &&
        deepEqual(init, cache.init)
      ) {

        // If an error occurred, throw it so that componentDidCatch can handle
        //   it.
        if (Object.prototype.hasOwnProperty.call(cache, 'error')) {
          throw cache.error;
        }

        // If a response was successful, return it.
        if (Object.prototype.hasOwnProperty.call(cache, 'response')) {
          if (metadata) {
            return {
              bodyUsed: cache.bodyUsed,
              contentType: cache.contentType,
              headers: cache.headers,
              ok: cache.ok,
              redirected: cache.redirected,
              response: cache.response,
              status: cache.status,
              statusText: cache.statusText,
              url: cache.url,
            };
          }
          return cache.response;
        }

        // If we are still waiting, throw the Promise so that Suspense can
        //   fallback.
        throw cache.fetch;
      }
    }

    // If no request in the cache matched this one, create a new cache entry.
    const cache: FetchCache = {

      // Make the fetch request.
      fetch: fetch(input, init)

        // Parse the response.
        .then((response: Response): Promise<FetchResponse> => {
          cache.contentType = response.headers.get('Content-Type');
          if (metadata) {
            cache.bodyUsed = response.bodyUsed;
            cache.headers = response.headers;
            cache.ok = response.ok;
            cache.redirected = response.redirected;
            cache.status = response.status;
            cache.statusText = response.statusText;
          }
          if (
            cache.contentType &&
            cache.contentType.indexOf('application/json') !== -1
          ) {
            return response.json();
          }
          return response.text();
        })

        // Cache the response.
        .then((response: FetchResponse): void => {
          cache.response = response;
        })

        // Handle an error.
        .catch((e: Error): void => {
          cache.error = e;
        })

        // Invalidate the cache.
        .then((): void => {
          if (lifespan > 0) {
            setTimeout(
              (): void => {
                const index: number = caches.indexOf(cache);
                if (index !== -1) {
                  caches.splice(index, 1);
                }
              },
              lifespan,
            );
          }
        }),
      init,
      input,
    };
    caches.push(cache);
    throw cache.fetch;
  }

  return useFetch;
};

const _export: Export = Object.assign(
  createUseFetch(), {
  createUseFetch,
  default: createUseFetch(),
});

export = _export;

