        imd = position - (Math.idiv(position, 4) * 4);
        widget.setCoordX((imd * 20) + ((imd + 1) * 4));//calculating x coordinate

        switch (length) {
            case WidgetLength.One_Quarter: //one_quarter
                widget.setWidth(20);
