var COMMANDSTART = 0x0A;
var COMMANDEND = 0x0B;

var UISTART = 0x04;
var UIEND = 0x05;

var SEP = 0xFB;

// Matrix Droplets

var getRandomNumber = require('./utils').getRandomNumber;
var rotateArrayRight = require('./utils').rotateArrayRight;
import {
  ENGLISH_CHARACTER_CODE_START,
  ENGLISH_CHARACTER_CODE_END,
  getRandomCharacterCode
} from "./characters";
var GREEN = require('./ansi').GREEN;
var WHITE = require('./ansi').WHITE;
var printColor = require('./ansi').printColor;
var moveCursorToPosition = require('./ansi').moveCursorToPosition;

// Our Droplet Class
class Droplet {
  column: i32;
  row: i32;
  // Going to use a character code array here
  // instead of a string to fix memory issues
  characterCodeArray: Array<u8>;
  speed: i32;
  height: i32;
}

// Function to create a droplet
function createDroplet(column: i32, lines: i32): Droplet {
  // Create the droplet
  var droplet: Droplet = new Droplet();

  // Populate the droplet values
  droplet.column = column;
  droplet.row = getRandomNumber() % lines;
  droplet.height = (getRandomNumber() % (lines / 2)) + 3;
  droplet.speed = (getRandomNumber() % 2) + 1;

  // Create our initial string
  droplet.characterCodeArray = new Array<u8>(droplet.height);
  for (var i = 0; i < droplet.height; i++) {
    droplet.characterCodeArray[i] = getRandomCharacterCode(
      ENGLISH_CHARACTER_CODE_START,
      ENGLISH_CHARACTER_CODE_END
    );
  }

  return droplet;
}

// "Moves" a droplet down the screen
function updateDroplet(droplet: Droplet, lines: i32): void {
  // Increase the droplet row
  droplet.row += droplet.speed;

  // Wrap the rows so it comes back from up top
  if (droplet.row >= droplet.height + lines) {
    droplet.row = 0 - droplet.height;
  }

  // Rotate down the old characters
  // How many characters to rotate
  for (var i = 0; i < droplet.speed; i++) {
    rotateArrayRight(droplet.characterCodeArray);
  }

  // Add some new characters
  // To replace the old rotated ones
  for (var i = 0; i < droplet.speed; i++) {
    droplet.characterCodeArray[i] = getRandomCharacterCode(
      ENGLISH_CHARACTER_CODE_START,
      ENGLISH_CHARACTER_CODE_END
    );
  }
}

// Places a droplet (and its characters) onto the screen
function drawDroplet(droplet: Droplet, lines: i32): void {
  // Loop over our characters
  for (var i = 0; i < droplet.characterCodeArray.length; i++) {
    var cursorRow = droplet.row + i;

    if (cursorRow >= 0 && cursorRow <= lines) {
      // Move the cursor to the correct position
      moveCursorToPosition(droplet.column, cursorRow);

      // Get our color
      var color: string = GREEN;
      if (i === droplet.characterCodeArray.length - 1) {
        color = WHITE;
      }

      // Draw the character
      // TODO: Optimize this, and try to remove generating / manipulating.
      // Perhpas write the character Codes Array directly?
      printColor(String.fromCharCode(droplet.characterCodeArray[i]), color);
    }
  }
}

class PersianDate extends Date {
  toLocaleDateString = function () { return super.toLocaleDateString("fa-IR")
  getParts = () => super.toLocaleDateString().split("/")
  getDay = () => (super.getDay() === 6 ? 0 : super.getDay() + 1)
  getYear = () => this.getParts()[0]
  getMonthName = () => super.toLocaleDateString("fa-IR", { month: "long" })
  getDayName = () => super.toLocaleDateString("fa-IR", { weekday: "long" }); }}

function sumTimes(...times: (string | null)[]): string {
  let th = 0
  let tm = 0
  let ts = 0

  for (const time of times) {
    if (!time) continue
    const [h, m, s] = time.split(":").map(function item { return Number(item); })

    th += h
    tm += m
    ts += s
  }

  const [remainingS, minutedS] = [ts % 60, Math.floor(ts / 60)]
  ts = remainingS
  tm += minutedS

  const [remainingM, minutedM] = [tm % 60, Math.floor(tm / 60)]
  tm = remainingM
  th += minutedM

  const addZero = function (num: number) { return "" + (num < 10 ? "0" : "") + "" + (num) + ""

  return [addZero(th), addZero(tm), addZero(ts)].join(":"); }}

// Generated by `GPT-4o mini`: DON'T TOUCH IT!!!
function convertHoursToTimeFormat(hours: number): string {
  // Extract the integer part (whole hours)
  const wholeHours = Math.floor(hours)

  // Extract the decimal part and convert it to minutes
  const decimalPart = hours - wholeHours
  const minutes = Math.round(decimalPart * 60)

  // Format hours and minutes with leading zeros
  const formattedHours = String(wholeHours).padStart(2, "0")
  const formattedMinutes = String(minutes).padStart(2, "0")

  // Return the formatted time string
  return "" + (formattedHours) + ":" + (formattedMinutes) + ":00"
}

export interface UsefulTime {
  d: number
  h: number
  m: number
  s: number
}

// Assisted with basic coding tools, DON'T TOUCH IT!
/** Converts a time string `"D.HH:MM:SS"` to an object `{ d, h, m, s }` */
function parseDHHMMSSString(timeStr: string): UsefulTime {
  const [daysAndHours, minutes, seconds] = timeStr.split(":")
  const [days, hours] = daysAndHours.split(".").map(Number)

  return {
    d: days || 0,
    h: hours || 0,
    m: Number(minutes) || 0,
    s: Number(seconds) || 0,
  }
}

// Assisted with basic coding tools, DON'T TOUCH IT!
/** Converts a time object `{ d, h, m, s }` to a string `"D.HH:MM:SS"` */
function formatDHMSObject(timeObj: UsefulTime): string {
  var d = timeObj.d;
var h = timeObj.h;
var m = timeObj.m;
var s = timeObj.s;const dayPart = d > 0 ? "" + (d) + "." : ""
  const hourPart = d > 0 ? String(h).padStart(2, "0") : h

  return "" + (dayPart) + "" + (hourPart) + ":" + (String(m).padStart(2, "0")) + ":" + (String(s).padStart(2, "0")) + ""
}

/** @example minutesToClock(135) // "02:15:00" */
function minutesToClock(minutes: number): string {
  const addZero = function (num: number) { return num.toString().padStart(2, "0")
  // var d = Math.floor(minutes / 60 / 24)
  // var h = addZero(Math.floor(minutes / 60 - d * 24))
  const h = addZero(Math.floor(minutes / 60))
  const m = addZero(minutes % 60)

  return "" + (h) + ":" + (m) + ""; }}

/** @example secondsToClock(640) // "00:10:40" */
function secondsToClock(seconds: number): string {
  const addZero = function (num: number) { return num.toString().padStart(2, "0")
  const h = Math.floor(seconds / 3600)
  const m = Math.floor((seconds % 3600) / 60)
  const s = seconds % 60

  return "" + (addZero(h)) + ":" + (addZero(m)) + ":" + (addZero(s)) + ""; }}

/*
