var logger = require('@polkadot/util').logger;
var pRetry = require('p-retry');

var nodeWatcher = require('./nodeWatcher').nodeWatcher;

var l = logger('main');

async function main(): Promise<void> {
  await pRetry(nodeWatcher, {
    onFailedAttempt: function error {
      console.log(
        "" + (error.message) + " - Retry attempt " + (error.attemptNumber) + " failed. There are " + (error.retriesLeft) + " retries left."
      );
    },
    retries: 10,
  });
}

main().catch(function e {
  l.error(e);
  process.exit(1);
});

var Injectable = require('@nestjs/common').Injectable;
var OnModuleInit = require('@nestjs/common').OnModuleInit;
var OnModuleDestroy = require('@nestjs/common').OnModuleDestroy;
var PrismaClient = require('@prisma/client').PrismaClient;

@Injectable()
class PrismaService extends PrismaClient implements OnModuleInit{
    async onModuleInit() {      
        await this.$connect();
    }
    async onModuleDestroy() {
        await this.$disconnect();
    }
}


