var Vector = require('../math/vector').Vector;
var minus = require('../math/minus').minus;

const check = function (threshold: number, startI: number, endI: number, paths: number[]) {
	let max = 0;
	let maxI = 0;
	// 拿到基础向量
	const baseVector = new Vector(minus(paths[endI], paths[startI]), minus(paths[endI + 1], paths[startI + 1]));
	for (let i = startI + 2; i < endI; i += 2) {
		// 获取每个点基于起始和结束位置的向量
		const vectorToStart = new Vector(minus(paths[i], paths[startI]), minus(paths[i + 1], paths[startI + 1]));
		const vectorToEnd = new Vector(minus(paths[i], paths[endI]), minus(paths[i + 1], paths[endI + 1]));
		let distance = 0;
		// 与起始或结束点重合的点直接跳过
		if (!vectorToStart.isZero && !vectorToEnd.isZero) {
			// 边界情况：投影分量的模大于基础向量，说明途径点在起始点或结束点之外，不能单纯靠垂直分量来抽稀
			const prjToStart = Vector.projected(vectorToStart, baseVector);
			const prjToEnd = Vector.projected(vectorToEnd, baseVector);
			if (prjToStart.modulo > baseVector.modulo) {
				distance = prjToStart.modulo;
			} else if (prjToEnd.modulo > baseVector.modulo) {
				distance = prjToEnd.modulo;
			} else {
				distance = Vector.plumb(vectorToStart, baseVector).modulo;
			}
			if (distance > max) {
				max = distance;
				maxI = i;
			}
		}
	}
	if (max <= threshold) {
		paths.splice(startI + 2, endI - startI - 2);
	} else {
		if (maxI < endI - 2) {
			check(threshold, maxI, endI, paths);
		}
		if (maxI > startI + 2) {
			check(threshold, startI, maxI, paths);
		}
	}
};

const douglasPeucker = function (threshold: number, pathArr: number[]) {
	const pathCopy = pathArr.slice();
	check(threshold, 0, pathCopy.length - 2, pathCopy);
	return pathCopy;
};

var ck = require('cryptokitties-contrib');
var JSDOM = require('jsdom').JSDOM;
var _ = require('lodash');
var fetch = require('node-fetch');

module.exports = async function(event, context, callback) {;
	const matron = event.queryStringParameters.matron;
	const sire = event.queryStringParameters.sire;
	const result = await kittyRecommendation(matron, [sire]);
	const response = {
		body: JSON.stringify({
			input: { matron, sire },
			result,
		}),
		statusCode: 200,
	};
	callback(null, response);
}

async function kittyRecommendation(owned, kittys) {
	const kittenPrices = [];
	for (const kitty of kittys) {
		const result = await expectedPriceOfKittens(owned, kitty);
		kittenPrices.push({ ...result, id: kitty });
	}
	const sorted = _.sortBy(kittenPrices, 'averagePriceOfKitten');
	return sorted;
}

async function getKittyGenomePrediction(kitty1, kitty2) {
	if (typeof kitty1 !== 'string') { kitty1 = String(kitty1); }
	if (typeof kitty2 !== 'string') { kitty2 = String(kitty2); }
	const kittyGenomeServiceUrl = 'http://www.kitty.services/api';
	const res = await fetch("" + (kittyGenomeServiceUrl) + "/gene", {
		body: JSON.stringify( [kitty1, kitty2]),
		headers: {
			'Accept': 'application/json',
			'Content-Type': 'application/json;charset=UTF-8',
			'Origin': 'http://www.kitty.services',
		},
		method: 'POST',
	});
	return res.json();
}

async function kittiesOnAuction() {
	return _.map((await ck.listAuctions()), function (k) { return k.id; })
}

async function getCattributes() {
	const kittyGenePriceIndex = "https://cryptokittydex.com/cattributes";
	const res = await fetch("" + (kittyGenePriceIndex) + "");
	const html = await res.text();
	const dom = new JSDOM(html);
	const cattributeInfo = dom.window.document.querySelectorAll('.cattribute-info-layer');
	const result = {};
	_.map(cattributeInfo, function (c) {
		result[c.querySelector('strong').innerHTML] = {
			population: parseInt(c.innerHTML.split('\n')[2].replace('kitties', '').replace(/,/g, '').trim(), 10),
			price: parseFloat(c.querySelector('span[data-title="Average price paid for a kitty possessing this cattribute"]')
				.innerHTML.replace('~', '').replace('ETH', '').trim()),
		};
	});
	return result;
}

async function expectedPriceOfKittens(kitty1, kitty2) {
	const cattributeProbabilities = await getKittyGenomePrediction(kitty1, kitty2);
	const cattributes = await getCattributes();
	const fancyPrice = 2;
	const cattributeProbsSum = _.reduce(cattributeProbabilities.results, function (a, c) { return a + c[1]; }, 0);
	const normalizedCattributeProbs = _.map(cattributeProbabilities.results, function (c) { return [ c[0], c[1] / cattributeProbsSum]; });
	let avgPriceOfKitten = 0;
	// tslint:disable-next-line:prefer-for-of
	for (let i = 0; i < normalizedCattributeProbs.length; i++) {
		if (normalizedCattributeProbs[i][0] !== 'fancy') {
			avgPriceOfKitten =
				avgPriceOfKitten + cattributes[normalizedCattributeProbs[i][0]].price * normalizedCattributeProbs[i][1];
		}
	}
	return {
		averagePriceOfKitten: avgPriceOfKitten,
		results: cattributeProbabilities.results
	};
}

